    def FirstConnect(self, value):
        """
        'set : FirstConnect. E.g., True/False based on OutExcel and MyAppendMode
        """
        calling_func = self.getCallingFuncName(2, clsName = self.__class__.__name__)
        self.logger.debug(f"{calling_func} - FirstConnect : value : {value}")
        if type(value) is bool:
            self.__firstConnect = value
        elif type(value) is int:
            if value > 1:
                self.__firstConnect = False
        else:
            self.__firstConnect = self.convertYNToBool(value)
        self.logger.debug("{0} - set : FirstConnect : {1}".format(calling_func, self.__firstConnect))
