    def DoPromptText(self, siteItem) :
        """
        ' base class method -- standard prompt to console -- child class should override if needed
        """
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        myPromptTxt = self.PromptText
        if self.IsEmptyOrNone(myPromptTxt) is True :
            myPromptTxt = "Getting Data from"
        #if self.IsEmptyOrNone(siteItem) is False :
        #    siteItem = "({0})".format(siteItem)
        #myPromptTxt = "{0} {1} ... {2}".format(myPromptTxt, siteItem, self.DatetimeNow)
