    def Repl_Col_Pattern_regexFile_GetLine1(self, site1, MyTable, MyPat=None, MyColSearch=None, MyAlias=None, MyPreHdr='', MyPostHdr=''):
        """
        'Helper function to process 'REGEX FILE' col-pattern for nqSQLiteTask
        """
        #region local variables
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        self.logger.debug("{0} - site1 : {1}".format(calling_func, site1))
