class nqHadoopImpalaTask(NormalQueryTaskBase):
    """
    Hadoop Impala Task handler
    """
    MyFetchSize = 50000
    def __init__(self, SPFTaskItemIn=None, SPFTaskItemIdxIn=None):
        super(nqHadoopImpalaTask, self).__init__(SPFTaskItemIn, SPFTaskItemIdxIn)
        calling_func = self.getCallingFuncName(2,clsName = self.__class__.__name__)
        #initialize/Overridden handler specific instance variables 
        self.logger.debug("{0} - nqHadoopImpalaTask Initialized".format(calling_func))
        return

    def performCommand(self):
        """
        ' Overridden from base
        """
        calling_func = self.getCallingFuncName(2,clsName = self.__class__.__name__)
        try : 
            if self.QType == 1 : 
                self.Run_Hadoop1(self.Sitei, self.SPFTaskCommand, self.WorkDir, self.OutTT, self.OutExcel, self.PromptText, 
                                 self.MyInstance, False, self.gMyLocal, self.MyTables, self.PreProcCSV, self.MySQLite_DT,
                                False)
                self.HadoopLeg = True
                IsHiveExt_output, SQLtbl2 = self.IsHiveExt(self.OutExcel, self.SQLtbl2)
                if IsHiveExt_output == True :
                    if SQLtbl2.find("_{0}".format(self.MyInstance)) == -1 :
                        self.Generate_Hive_Schema(self.ll_hadoopSvr, SQLtbl2, myInstance=self.gSPFInstance)
            else : 
                self.Run_Hadoop1(self.Sitei, self.SPFTaskCommand, self.WorkDir, self.OutTT, self.SQLtbl2, self.PromptText, 
                                 self.MyInstance, False, self.gMyLocal, self.MyTables, self.PreProcCSV, self.MySQLite_DT,
                                False)
            self.Send_To_Term(self.OutExcel, self.OutTT, self.ll_NoHdrs, queryOptions=self.queryOptions)
        except Exception as err:
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise

