class CB_ACSTask(SPFTaskBase) :
    """
    '==========================================================
    'Run a CB ACS File
    '
    'ARGS:
    '====
    'MyCBACS   : CB ACS Text
    'OutExcel  : Name of CSV file to write output to, else empty
    'WorkDir   : Work Folder
    'MyInstance: SPF Instance Number
    '
    'GLOBALS:
    '-------
    'gMyAbort : Whether to Abort job
    '==========================================================
    """
    #locals
    q2 = None

    def __init__(self, SPFTaskItemIn=None, SPFTaskItemIdxIn=None):
        super(self.__class__, self).__init__(SPFTaskItemIn, SPFTaskItemIdxIn)
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        self.logger.debug("{0} - CB_ACSTask Initialized".format(calling_func))
        return None
        
    def execute(self):
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        try : 
            super(CB_ACSTask, self).execute()
            self.Console("Starting Crystal Ball Applet, v1.2 .... {0}\n".format(self.DatetimeNow))
            MyCBType = "Production"
            if bool(re.search("CRYSTALBALL_PROTO", self.SPFTaskCommand, re.IGNORECASE|re.MULTILINE)) == True :
                MyCBType = "Prototype"
            self.Console("Crystal Ball Mode= {0}".format(MyCBType))
            dbDriver = dbDriverCB()
            dbDriver.openConnection("cbcli.exe", MyCBType)
            dbDriver.execute(self.SPFTaskCommand, self.OutExcel, self.WorkDir, self.MyInstance)
            self.ConsoleDoneWithTimeStamp()
        except Exception as err: 
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise
#END : class CB_ACSTask

class StackDataTask(SPFTaskBase) :
    """
    '******************************************************************
    'Stack Tables on top of each other based on col names, & optionally
    'apply a Sort on unioned Results
    '
    'ARGS
    '===
    'MyTables  : comma dlm list of tables to Stack
    'MySortCols: Comma Dlm List of Cols to Sort & Sort order.
    '            E.g., lot ASC, Oper DESC
    'WorkDir   : Work Dir
    'outTT     : O/P to Term or Not (empty)
    'outFile   : O/P to File or Not. No o/p if Empty. May contain {TAB} in name
    'outExcel  : O/p to Excel or Not (Empty)
    '******************************************************************
    """
    #locals
    myCon = None

    def __init__(self, SPFTaskItemIn=None, SPFTaskItemIdxIn=None):
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        super(StackDataTask, self).__init__(SPFTaskItemIn, SPFTaskItemIdxIn)
        self.logger.debug("{0} - StackDataTask Initialized".format(calling_func))
        return None
    
    def getColDTypeBasedOnSortCols(self, all_cols, MySortCols):
        """
        determine the datatype of col in 'all_cols' E.g., string or numeric based on sort specified in 'MySortCols'
        E.g., lot asc --> str
        qty desc-1 --> float
        Input : 
        1. all_cols : list of all cols E.g., [lot, qty]
        2. MySortCols : CSV string of sort spec E.g., [lot] asc, [qty] desc-1 
        """
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        dtype = object #default
        try:
            MySortColsNames = MySortCols.split(",")

            dtype=dict(zip(all_cols, [str for MySortColsItem in all_cols]))

            for MySortColsItem in MySortColsNames:
                self.logger.debug("{0} - MySortColsItem : {1}".format(calling_func, MySortColsItem))
                item_col_info = MySortColsItem.split("] ")
                self.logger.debug("{0} - item_col_info : {1}".format(calling_func, item_col_info))
                if len(item_col_info) > 0:
                    if item_col_info[1].endswith("-1") is True:
                        colName = item_col_info[0].strip("[]")
                        self.logger.debug("{0} - colName : {1}".format(calling_func, colName))
                        dtype[self.getMatchingValFrmList(colName, dtype.keys())] = float
        except Exception as err:
            self.logger.warning("{0} - {1}...continue MySortCols is empty".format(calling_func, err))
            pass #error due to MySortCols is None
        self.logger.debug("{0} - dtype : {1}".format(calling_func, dtype))
        return dtype



    def getAllColsAndDelimFromFilesList(self, filesList) :
        """
        ' get all columns from file list and also dilimiter for file
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        allCols_output = []
        allFilesFileDLMList = []
        allFileColsList = []
        self.logger.debug("{0} - filesList: {1}".format(calling_func, filesList))
        try : 
            #import pandas as pd
            #dfList = []
            for fileItem in filesList :
                srcFileDLM = self.GetFileDLM(fileItem)
                
                cols = self.GetHeadersFromFile(fileItem, convertToUpperCase=True)
                allFileColsList.append(cols) #add this to the list, which will be used later
                for colItem in cols :
                    matchingColName =  colItem
                    try:
                        matchingColName = self.getMatchingValFrmList(matchingColName, allCols_output)
                    except Exception as err:
                        self.logger.warn("{0} - {1}...continue matching value not found".format(calling_func, err.args[0]))
                        allCols_output.append(colItem) # add to list

                allFilesFileDLMList.append(srcFileDLM)

            self.logger.debug("{0} - allCols_output: {1}".format(calling_func, allCols_output))
            self.logger.debug("{0} - allFilesFileDLMList: {1}".format(calling_func, allFilesFileDLMList))
            return allCols_output, allFilesFileDLMList, allFileColsList
        except Exception as err: 
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise

    def getTotalSizeOfAllFilesInList(self, filesList) : 
        """
        ' returns Total size of all files in a list
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        self.logger.debug("{0} - filesList: {1}".format(calling_func, filesList))
        filesSizeList = []
        allFilesTotalSize_output = 0
        try : 
            for fileItem in filesList : 
                fileItemSize = os.path.getsize(fileItem)
                self.logger.debug("{0} - fileItemSize: {1}".format(calling_func, fileItemSize))
                filesSizeList.append(fileItemSize)
            self.logger.debug("{0} - filesSizeList: {1}".format(calling_func, filesSizeList))
            allFilesTotalSize_output = sum(filesSizeList)
            self.logger.debug("{0} - allFilesTotalSize_output: {1}".format(calling_func, allFilesTotalSize_output))
            return allFilesTotalSize_output
        except Exception as err: 
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise
    
    def execute(self):
        """
        '   VA logic implementation uses pandas for parsing input files and SQLite for union/sort
        """
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        try : 
            super(StackDataTask, self).execute()
            self.Console("Starting Interleave Results, v1.0 .... {0}\n".format(self.DatetimeNow))
            colsDict  = {}
            all_cols = None
            myMemTable = MemTable()
            
            tblsToLoadList = self.MyTables.split(",")
            self.logger.debug("{0} - tblsToLoadList: {1}".format(calling_func, tblsToLoadList))
            totalSizeofAllFiles = self.getTotalSizeOfAllFilesInList(tblsToLoadList)
            all_cols, allFilesFileDLMList, allFileColsList = self.getAllColsAndDelimFromFilesList(tblsToLoadList)
            import pandas as pd
            dfTemplate = pd.DataFrame(columns=all_cols)
            if_exists = 'replace'
            outExcelFilePath, outExcelFileName = os.path.split(self.OutExcel)
            #outExcelFileName = "tmpStackTable"
            while len(tblsToLoadList) > 0 :
                tblToLoad = tblsToLoadList.pop(0)
                tblDLM = allFilesFileDLMList.pop(0)
                tblCols = allFileColsList.pop(0)
                dfReader = pd.read_csv(filepath_or_buffer=tblToLoad, sep=tblDLM, na_filter=False, chunksize=50000, dtype=self.getColDTypeBasedOnSortCols(all_cols, self.MySortCols)
                                       , encoding=self.detectFileEncoding(tblToLoad))
                
                for dfChunk in dfReader :
                    dfChunk.columns = tblCols
                    if (pd.__version__ + '    ')[:4] < '0.24':
                        dfChunkConcatAllCols = pd.concat([dfChunk, dfTemplate])[all_cols] #concat chunks and select with correct column order
                    else:
                        # dfChunkConcatAllCols = pd.concat([dfChunk, dfTemplate], sort=True)[all_cols] #concat chunks and select with correct column order
                        dfChunkConcatAllCols = dfChunk.reindex(columns=all_cols, fill_value='') #fix for Py3.13
                    del dfChunk
                    myMemTable.LoadDF(dfChunkConcatAllCols, '[{0}]'.format(outExcelFileName), if_exists)
                    if_exists = 'append'
            if self.IsEmptyOrNone(self.MySortCols) == False :
                self.logger.debug("{0} - MySortCols : {1}".format(calling_func, self.MySortCols))
                sqlQueryFinal = "SELECT * FROM '[{0}]' ORDER BY {1}".format(outExcelFileName, self.MySortCols.replace('-1',''))
            else :
                sqlQueryFinal = "SELECT * FROM '[{0}]'".format(outExcelFileName)
            myCursor = myMemTable.Run_SQLQuery(sqlQueryFinal)
            rowsWritten = myMemTable.writeCursorToFile(myCursor, None, self.OutExcel, self.OutTT, ll_QuoteCSV=self.ll_QuoteCSV)
            self.Send_To_Term(self.OutExcel, self.OutTT, self.ll_NoHdrs, ll_QuoteCSV=self.ll_QuoteCSV, queryOptions=self.queryOptions, totalRecsInFile=rowsWritten)
            # self.ConsoleDoneWithTimeStamp()
        except Exception as err: 
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise
#END : class StackDataTask

