class RowsInFileTask(SPFTaskBase) :
    def __init__(self, SPFTaskItemIn=None, SPFTaskItemIdxIn=None):
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        super(RowsInFileTask, self).__init__(SPFTaskItemIn, SPFTaskItemIdxIn)
        self.logger.debug("{0} - RowsInFileTask Initialized".format(calling_func))
        return None

    def executeTaskCommand(self):
        """
        ' Overridden base method 
        ' implementation of Set_Rows_In_File
        '=====================================
        'Counts rows in file & assign to env var
        ' supported file formats .csv, .tab, .zip, .parquet
        'ARGS:
        '----
        'MyArg: YAS_NCDD.csv;RowsInFile -- in py these are derived directly from query
        '; separated list of file to count &
        'env var to set.
        '=====================================
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        fileToScan = None
        envVarToSet = None
        limitRowCountTo1 = "N"
        archiveFileName = None # 'file name' archived in the .zip file on which rowcounting is needed
        errMsg = ""

        try :
            self.Write_Prompt()

            try :
                fileToScan = self.MyUtilities[1]
                self.Console("Counting Rows in File: {0}".format(fileToScan))

                envVarToSet = self.MyUtilities[2]
                self.logger.debug("{0} - envVarToSet : {1}".format(calling_func, envVarToSet))

                if len(self.MyUtilities) > 3:
                    limitRowCountTo1 = self.MyUtilities[3].strip().upper()
                self.logger.debug("{0} - limitRowCountTo1 : {1}".format(calling_func, limitRowCountTo1))

                if len(self.MyUtilities) > 4:
                    archiveFileName = self.MyUtilities[4].strip()
                self.logger.debug("{0} - archiveFileName : {1}".format(calling_func, archiveFileName))

            except Exception as err:
                self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
                raise

            try : 
                if limitRowCountTo1 == "Y":
                    recsInFile = self.getRowCountFromFile(fileToScan, countLimit=1, zipFileArchiveName=archiveFileName)
                else :
                    recsInFile = self.getRowCountFromFile(fileToScan, zipFileArchiveName=archiveFileName)

            except Exception as err:
                self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
                recsInFile = -1
                errMsg = " - {0}".format(err.args[0]) #"- File not Found"

            self.logger.debug("{0} - recsInFile : {1}\n".format(calling_func, recsInFile))
            self.setEnv(envVarToSet, recsInFile)
            self.Console("  Row Count is {0} {1}\n".format(recsInFile, errMsg))
        except Exception as err: 
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise
#END : class RowsInFileTask

class ValueInFileTask(SPFTaskBase) :
    def __init__(self, SPFTaskItemIn=None, SPFTaskItemIdxIn=None):
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        super(ValueInFileTask, self).__init__(SPFTaskItemIn, SPFTaskItemIdxIn)
        self.logger.debug("{0} - ValueInFileTask Initialized".format(calling_func))
        return None

    def executeTaskCommand(self):
        """
        ' Overridden base method 
        ' implementation of Set_Value_In_File
        '================================
        'Gets value in 1st row of a named col in a 
        'file, & assigns value to an env var
        'ARGS:
        '----
        'MyArg: YAS_NCDD.csv;MyData;Lot
        'semicolon separated list of file to process,
        'env var to set, & col to query
        '================================
        sample input line: /UTILITIES={VALUE-IN-FILE} "deltaFile.tab" "MyData" "LOT"
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        fileToScan = None
        envVarToSet = None
        colToRead = None
        colValue = "ERROR"
        errMsg = ""

        try :
            self.Write_Prompt()
            try :
                fileToScan = self.MyUtilities[1]
                self.logger.debug("{0} - fileToScan : {1}".format(calling_func, fileToScan))
                self.Console("File to process: {0}".format(fileToScan))
                
                envVarToSet = self.MyUtilities[2]
                self.logger.debug("{0} - envVarToSet : {1}".format(calling_func, envVarToSet))

                colToRead = self.MyUtilities[3]
                self.logger.debug("{0} - colToRead : {1}".format(calling_func, colToRead))

                #check if file exists
                if os.path.exists(fileToScan) == False :
                    errMsg = "Could not locate file {0}".format(fileToScan)
                    raise Exception(errMsg)

                #check if col exists
                allColsInFile = self.GetHeadersFromFile(fileToScan)
                try:
                    colToRead = self.getMatchingValFrmList(colToRead, allColsInFile)
                    self.logger.debug("{0} - colToRead : {1}".format(calling_func, colToRead))
                except IndexError as IdxErr:
                    self.logger.exception("{0} - {1}".format(calling_func, IdxErr[0]))
                    errMsg = "Could not locate column {0} in file {1}".format(colToRead, fileToScan)
                    raise Exception(errMsg)
                
                #check if file has atleast 1 row
                rowCountLimitedTo1 = self.getRowCountFromFile(fileToScan,countLimit=1)
                self.Console(" Assigning value of column {0} for row 1 to {1}".format(colToRead, envVarToSet))
                if rowCountLimitedTo1 == 0 :
                    #empty file with only headers
                    colValue = 'EMPTY'
                else : #has atleast 1 row...get value
                    import pandas as pd

                    df1 = pd.read_csv(filepath_or_buffer=fileToScan, sep=self.GetFileDLM(fileToScan), 
                        keep_default_na = False, 
                        nrows=1, #just read 1st row
                        usecols=[colToRead], dtype=str)
                    #now get the value
                    colValue = df1[colToRead][0]
                    del df1
                self.Console(" Value is {0}\n".format(colValue))
            except Exception as err:
                self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
                self.Console('{0}. {1} set to "{2}"\n'.format(err.args[0], 
                                                                envVarToSet, 
                                                                colValue))
            #set the envVar
            self.setEnv(envVarToSet, colValue)
        except Exception as err: 
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise
#END : class ValueInFileTask

class AgeOfFileTask(SPFTaskBase) :
    def __init__(self, SPFTaskItemIn=None, SPFTaskItemIdxIn=None):
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        super(AgeOfFileTask, self).__init__(SPFTaskItemIn, SPFTaskItemIdxIn)
        self.logger.debug("{0} - AgeOfFileTask Initialized".format(calling_func))
        return None

    def executeTaskCommand(self):
        """
        ' Overridden base method : implementation of VA Get_Age_Of_File
        '================================
        'Gets file age in hours. Returns
        'difference between date
        'file last modified & now
        'ARGS:
        '----
        'MyArg: YAS_NCDD.csv;AgeofFile or YAS_NCDD.csv;AgeofFile;HOURS 
        'semicolon separated list of file to process, Env Var to set
        '& units of time for age computation. Default is hours
        '================================
        sample input line: /UTILITIES={AGE-OF-FILE} "deltaFile.tab" "AgeOfFile" "Hours"
        """
        def calcDateDiff(duration) : 
            """
            ' nested function to calculate dateDiff in various units from timedelta duration
            """
            totseconds = abs(int(duration.total_seconds()))
            days, seconds = divmod(totseconds, 86400)
            hours, seconds  = divmod(totseconds, 3600)
            minutes, seconds = divmod(totseconds, 60)     
            calcDateDiffRetVal = {"DAYS" : days, "HOURS" : hours, "MINUTES" : minutes, "SECONDS" : totseconds}
            self.logger.debug("{0} - retVal : {1}".format(calling_func, calcDateDiffRetVal))
            return calcDateDiffRetVal
        #END : def calcDateDiff(duration) :  # nested method

        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        fileToScan = None #T1
        envVarToSet = None #T2
        diffUnits = None #T3
        diffValue = "-1" #default value if any error
        validUnits = ["DAYS", "HOURS", "MINUTES", "SECONDS"]
        errMsg = ""

        try :
            self.Write_Prompt()
            self.Console("Age of File Utility, v 1.1... {0}".format(self.DatetimeNow))
            try :
                fileToScan = self.MyUtilities[1]
                self.logger.debug("{0} - fileToScan : {1}".format(calling_func, fileToScan))
                self.Console("  File to process: {0}".format(fileToScan))
                
                envVarToSet = self.MyUtilities[2]
                self.logger.debug("{0} - envVarToSet : {1}".format(calling_func, envVarToSet))
                if self.IsEmptyOrNone(envVarToSet) is True :
                    errMsg = ("Missing Environment Variable. Problems can occur if file has semicolon in name:\n"
                              "  File to process: {0}\n"
                              "  Environment Var: {1}").format(fileToScan, envVarToSet)
                    #self.ConsoleWithCons80(errMsg)
                    raise Exception(errMsg) # raise exception

                diffUnits = self.MyUtilities[3].upper()
                self.logger.debug("{0} - diffUnits : {1}".format(calling_func, diffUnits))

                #check if units is in validUnits list...if not default
                if diffUnits not in validUnits : 
                    diffUnits = "HOURS"
                    self.logger.debug("{0} - not found updated diffUnits : {1}".format(calling_func, diffUnits))

                #check if file exists
                if os.path.exists(fileToScan) == False :
                    errMsg = "Could not locate file {0}".format(fileToScan)
                    raise Exception(errMsg)
                
                self.Console("  Assigning Age of File to: {0}".format(envVarToSet))
                self.Console("  Units of Time for Age will be: {0}".format(diffUnits.capitalize()))
                fileLastModtime = datetime.fromtimestamp(os.stat(fileToScan).st_mtime)
                self.Console("  File was last modified on {0}".format(datetime.strftime(fileLastModtime
                                                                                        , self.G_DT_FORMAT_DD_MON_YYYY_HH24_MM_SS)))
                durationDelta = datetime.now() - fileLastModtime
                diffValue = calcDateDiff(durationDelta)[diffUnits]
                self.Console("  File is {0} {1} old ...\n".format(diffValue, diffUnits.capitalize()))
            except Exception as err:
                self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
                self.Console('{0}. {1} set to "{2}"\n'.format(err.args[0], 
                                                                envVarToSet, 
                                                                diffValue))
            #set the envVar
            self.setEnv(envVarToSet, diffValue)
            self.ConsoleDoneWithTimeStamp2()
        except Exception as err: 
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise
#END : class AgeOfFileTask

