class vaTask(SPFTaskBase) :
    
    __MyUtilities = None
    @property
    def MyUtilities(self) :
        """
        ' override SPFTaskBase property for custom implementation
        'get : scrubbed MyUtilitiesValue 
        """
        calling_func = self.getCallingFuncName(2, clsName = self.__class__.__name__)
        if self.__MyUtilities is None : 
            self.logger.debug("{0} - MyUtilitiesValue : {1}".format(calling_func, self.MyUtilitiesValue))
            if self.MyUtilitiesValue is not None :
                tmpCSVRdr = csv.reader(StringIO(self.MyUtilitiesValue), delimiter=" ", skipinitialspace=True, quotechar='"') 
                self.__MyUtilities = [item1.strip(' ') #strip ' '
                                        for item1 #SELECT
                                        in next(tmpCSVRdr) #FROM
                                        if self.IsEmptyOrNone(item1) is False #where item is not empty or None
                                      ] 
            #END:  if self.MyUtilitiesValue is not None
        self.logger.debug("{0} - MyUtilities : {1}".format(calling_func, self.__MyUtilities))
        return self.__MyUtilities

    def __init__(self, SPFTaskItemIn=None, SPFTaskItemIdxIn=None):
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        super(vaTask, self).__init__(SPFTaskItemIn, SPFTaskItemIdxIn)
        self.logger.debug("{0} - vaTask Initialized".format(calling_func))
        return None

    def executeTaskCommand(self):
        """
        ' overridden base method
        ' Handle routing to correct py handler of VA script
        """
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        
        vaScriptsMap = {'Generate_Hive_Schema.va' : ("nqHadoopTask","executeGenerateSchema"),
                        'Generate_Any_Schema.va' : ("GenAnySchemaTask","executeGenerateSchema")}

        try :
            self.Write_Prompt()
            
            vaFileWithPath = self.MyUtilities[1].strip('" ') #strip any ", ' '
            self.logger.info("{0} - vaFileWithPath: {1}".format(calling_func,vaFileWithPath))

            vaFilePath, vaFileName = os.path.split(vaFileWithPath)
            self.logger.info("{0} - vaFilePath: {1}".format(calling_func,vaFilePath))
            self.logger.info("{0} - vaFileName: {1}".format(calling_func,vaFileName))

            vaFileArgs = self.MyUtilities[2:]
            self.logger.info("{0} - vaFileArgs: {1}".format(calling_func,vaFileArgs))

            try :
                TaskHandlerName, HandlerFuncName = vaScriptsMap[vaFileName]#.split(',')
                self.logger.debug("{0} - TaskHandlerName: {1}".format(calling_func, TaskHandlerName))
                self.logger.debug("{0} - HandlerFuncName: {1}".format(calling_func, HandlerFuncName))
            except Exception as err: 
                self.logger.warn("{0} - {1}\n...continue".format(calling_func, err.args[0]))
                self.logger.debug("{0} - HandlerFuncName not found run the va script : {1}".format(calling_func, vaFileWithPath))
                try :
                    cmdToExecute = self.MyUtilities.pop(0)
                    self.MyUtilities[0] = '"{0}"'.format(self.MyUtilities[0])
                    cmdArgs = self.MyUtilities
                    runStatus, runCode = self.Run(cmdToExecute, cmdArgs)
                    return
                except Exception as err: 
                    self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))        
                    raise
            try:
                TaskHandlerClsObject = getattr(sys.modules[__name__], TaskHandlerName)
                myTask = TaskHandlerClsObject()
                myFunc = getattr(myTask, HandlerFuncName)
                #myTask.executeGenerateSchema(vaFileArgs)
                myFunc(vaFileArgs)
            except Exception as err: 
                self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
                raise
        except Exception as err: 
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise
#END : class vaTask

