class Run_JSLTask(SPFTaskBase) :
    def __init__(self, SPFTaskItemIn=None, SPFTaskItemIdxIn=None):
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        super(Run_JSLTask, self).__init__(SPFTaskItemIn, SPFTaskItemIdxIn)
        self.logger.debug("{0} - Run_JSLTask Initialized".format(calling_func))
        return None

    #status : dev done, UT WIP
    def executeTaskCommand(self):
        """
        ' Overridden base method, redirector to Run_JSL & Run_JSL2
        sample input line: /JSL=Y
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        IsSignal = False #default value
        signalInstance = None
        try :
            self.Write_Prompt()

            if self.gMyLocal == "N" or self.gRunMode == "IB":
                signalInstance = 1
            else :
                signalInstance = self.gSPFInstance
                
            #END : if self.gMyLocal == "N" or self.gRunMode == "IB" :
            sigFile = r".\spf_signal_Test_{0}.bat".format(signalInstance)
            waitFile = r".\{0}.wait".format(signalInstance)
            htmFile = r".\Test_{0}.htm".format(signalInstance)
            self.DelAFile(sigFile)
            self.DelAFile(waitFile)

            if self.gMyLocal == "N" or self.gRunMode == "IB" or self.gIsSvc is True: #add SQLPFaaS execution check
                IsSignal = self.Run_JSL(self.gMyLocal, self.SPFTaskCommand, IsSignal)
            else:
                IsSignal = self.Run_JSL2(self.SPFTaskCommand, signalInstance, IsSignal)

            if IsSignal == True :
                self.Chk_Signal(sigFile, signalInstance)
                self.DelAFile(waitFile)
                self.DelAFile(htmFile)
        except Exception as err : 
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise
    #END : def executeTaskCommand

    #status : dev done, UT WIP
    def Run_JSL(self, MyLocal, MyCommand, IsSignal) :
        """
        '=======================================================
        'Load CSV File to JMP or Load CSV File & run a JSL Script
        '
        'Args:
        '====
        'MyLocal  : N if remote, else exe dir
        'MyCommand: JSL Script
        'IsSignal : PPT/Email Signal
        '========================================================
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        self.logger.debug("{0} - MyLocal: {1}".format(calling_func,MyLocal))
        self.logger.debug("{0} - MyCommand: {1}".format(calling_func,MyCommand))
        self.logger.debug("{0} - IsSignal: {1}".format(calling_func,IsSignal))
        DoCloseJMP = False 
        JMPObj = None

        try :
            self.Console("\nStarting JMP/JSL Applet ... v3.0 {0}".format(self.DatetimeNow))
            MyDefDir = os.path.curdir
            if self.IsEmptyOrNone(MyDefDir) is True :
                MyDefDir = ".\\"
            MyDefDir = "{0}\\".format(os.path.abspath(MyDefDir))
            self.logger.debug("{0} - MyDefDir: {1}".format(calling_func, MyDefDir))
            L2 = 'DEFAULT_DIR="{0}";set default directory (::DEFAULT_DIR);'.format("{0}\\".format(MyDefDir) if MyDefDir[-1] != "\\" else MyDefDir)
            self.Console("   The following JSL Code will be executed before your script ...\n     {0}\n".format(L2))
            L2 = "{0}\n{1}".format(L2, MyCommand) 
            L2 = L2.replace("$default$dir$", MyDefDir)
            L2 = L2.replace("$py$exe$dir$", sys.executable)
            if L2.lower().find("dojmp.va") > -1 or L2.lower().find("dojmp.py") > -1 :
                IsSignal = True
            if L2.lower().find("test_$instance$.htm") > -1 :
                self.DelAFile(r".\Test_{0}.htm".format(1))
            if IsSignal == True :
                L2 = '{0}\n\nSave Text File (::Default_Dir || "$instance$.wait","");'.format(L2)
            self.logger.debug("{0} - L2: {1}".format(calling_func,L2))
            self.logger.debug("{0} - type(L2): {1}".format(calling_func,type(L2)))
            L2 = L2.replace("$instance$", '1') #'Substitute Inst#
            self.logger.debug("{0} - replaced $instance$ L2: {1}".format(calling_func,L2))
            if self.SHisSHEntry is True:
                JMPObj, DoCloseJMP = self.StartJMP(MyLocal, LeaveJMPOpen=False)
            else:
                JMPObj, DoCloseJMP = self.StartJMP(MyLocal, LeaveJMPOpen=True)

            """
            '=====================
            'Break Script into JMP
            'cmds & run each cmd
            '=====================
            """
            MyJSLi = L2.split(";;")
            JMPObj.ClearLog
            self.Console("   Running Script ...\n")
            for jslItem in MyJSLi :
                if self.IsEmptyOrNone(jslItem.strip()) is False:
                    try :
                        #'Run each statement
                        JMPObj.RunCommand("{0};".format(jslItem))
                    except Exception as err: 
                        self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
                        jBool = JMPObj.HasRunCommandErrorString
                        if jBool == True :
                            errMsg = ("Error executing JSL: {0}\n"
                                      "Script Fragment Run was:\n {1};"
                                      ).format(JMPObj.GetRunCommandErrorString,
                                               jslItem)
                            self.ConsoleWithCons80(errMsg)
                            self.Console("\n=================== JMP Log Window =====================================")
                            self.Console(JMPObj.GetLogContents)
                            self.Console("=================== End Log Window =====================================\n")
                        else : 
                            errMsg = "A Trapped error occurred in JSL phrase:\n {0}".format(jslItem)
                        break
            #END : for

            self.ConsoleDoneWithTimeStamp()
            return IsSignal
        except Exception as err: 
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise
        finally:
            """
            '**************************************
            'Clean Up. For interact. use, ~close JMP
            '**************************************
            """
            try:
                if DoCloseJMP is True: 
                    if not JMPObj is None:
                        JMPObj.quit()
                        JMPObj = None
                        time.sleep(2) #need to give time for JMP to close completely else image file auto naming counters get's corrupted. Very rare occurances but this is the only way to handle this
                        self.logger.debug("{0} JMPObj closed".format(calling_func))
            except pywintypes.com_error as pyWComErr:
                if pyWComErr.hresult == -2147417848 and pyWComErr.strerror == 'The object invoked has disconnected from its clients.':
                    self.logger.debug("{0} JMPObj is already closed, it may have embedded 'Exit' statement resulting in com_error : {1}...continue".format(calling_func, pyWComErr))
                else:
                    raise
            except Exception as err:
                self.logger.exception("{0} finally block error - {1}".format(calling_func, err))
                raise


    #status : dev done, UT WIP
    def Run_JSL2(self, MyCommand, MyInstance, IsSignal) :
        """
        '========================
        'Runs JSL Script Interactively
        '
        'Args:
        '====
        'MyCommand : JSL Script
        'MyInstance: SPF Inst. #
        'IsSignal  : Email/PPT Signal
        '==========================        
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        self.logger.debug("{0} - MyCommand: {1}".format(calling_func, MyCommand))
        self.logger.debug("{0} - MyInstance: {1}".format(calling_func, MyInstance))
        self.logger.debug("{0} - IsSignal: {1}".format(calling_func, IsSignal))

        try :
            self.Console("\nStarting JMP/JSL Applet ... v1.2 {0}".format(self.DatetimeNow))
            if self.IsEmptyOrNone(MyInstance) == True :
                RN = self.RandomNumStr
                JSLFile = "{0}.jsl".format(RN)
            else :
                JSLFile = "{0}.jsl".format(MyInstance)
            JSLFile = os.path.abspath(JSLFile)
            self.logger.debug("{0} - JSLFile: {1}".format(calling_func, JSLFile))
            MyDefDir,_ = os.path.split(JSLFile)
            if self.IsEmptyOrNone(MyDefDir) is True :
                MyDefDir = ".\\"

            MyDefDir = os.path.abspath(MyDefDir)
            if MyDefDir[-1] != "\\":
                MyDefDir = "{0}\\".format(MyDefDir)
            self.logger.debug("{0} - MyDefDir: {1}".format(calling_func, MyDefDir))

            L1 = 'DEFAULT_DIR="{0}";set default directory (::DEFAULT_DIR);'.format("{0}\\".format(MyDefDir) if MyDefDir[-1] != "\\" else MyDefDir)
            self.Console("   The following JSL Code will be executed before your script ...\n     {0}\n".format(L1))
            L1 = "//!\n{0}\n{1}".format(L1, MyCommand) #'Add Autorun to top of JSL file to execute
            L1 = L1.replace("$default$dir$", MyDefDir)
            L1 = L1.replace("$py$exe$dir$", sys.executable)
            self.logger.debug("{0} - replaced $instance$ L1: {1}".format(calling_func,L1))
            """
            '================================
            'If email, remove exist. htm file
            '================================
            """
            if L1.lower().find("dojmp.va") > -1 or L1.lower().find("dojmp.py") > -1 :
                IsSignal = True
            if L1.lower().find("test_$instance$.htm") > -1 :
                self.DelAFile(os.path.join(".\\", "Test_{0}.htm".format(MyInstance)))
                self.SPFDelete(r".\gfx\*.*")
            if IsSignal == True :
                L1 = '{0}\n\nSave Text File (::Default_Dir || "$instance$.wait","");'.format(L1)
            L1 = L1.replace("$instance$", MyInstance) #'Inst#

            self.DoCreateFileA(JSLFile, L1,"Run_JSL2")
            self.Console("   Running Script ...")
            
            cmdToExecute = "%COMSPEC%"
            cmdArgs = ['/c', 'start', '""', '"{0}"'.format(JSLFile)]
            runJSL2_status, runExitCode = self.Run(cmdToExecute, cmdArgs)

            if self.IsEmptyOrNone(MyInstance) == True :
                self.DelAFile(JSLFile)
            self.ConsoleDoneWithTimeStamp()
            return IsSignal
        except Exception as err: 
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise
#END : class JSLTask

class LoadJMPTask(SPFTaskBase) :
    def __init__(self, SPFTaskItemIn=None, SPFTaskItemIdxIn=None):
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        super(LoadJMPTask, self).__init__(SPFTaskItemIn, SPFTaskItemIdxIn)
        self.logger.debug("{0} - SPFDeleteTask Initialized".format(calling_func))
        return None

    def executeTaskCommand(self):
        r"""
        ' Overridden base method, implementation of LoadJMP
        '================================
        'Load CSV File to JMP & optionally run a JSL Script
        '================================
        sample input line: /UTILITIES=@EXEDIR@\LoadJMP.va "None" "test1.jsl" "N"
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        B1 = r".\{0}.bat".format(self.RandomNumStr) # Work File - deleted @end of job
        MyCSVFile = None # CSV File to Import
        JMPFile = None # JMP File to Save Results to [Default = SQLPathFinder.jmp in def folder]
	                   # or opt. Path to JSL to run [Default = NONE].
        LeaveJMPOpen = False # True ('Y') to leave JMP open after execution. Interactive use only

        try :
            self.Write_Prompt()
            MyCSVFile = self.MyUtilities[1]
            JMPFile = self.MyUtilities[2]
            self.logger.info("{0} - B1: {1}".format(calling_func,B1))
            self.logger.info("{0} - MyCSVFile: {1}".format(calling_func,MyCSVFile))
            self.logger.info("{0} - JMPFile: {1}".format(calling_func,JMPFile))
            try :
                LeaveJMPOpen = self.convertYNToBool(self.MyUtilities[3])
            except Exception as err: 
                pass #continue with default value

            self.logger.info("{0} - LeaveJMPOpen: {1}".format(calling_func,LeaveJMPOpen))
            return self.LoadJMP(B1, MyCSVFile, JMPFile, LeaveJMPOpen, self.gMyLocal)
        except Exception as err: 
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise
    #END : def executeTaskCommand

    def LoadJMP(self, B1, MyCSVFile, JMPFile, LeaveJMPOpen, MyLocal) :
        """
        '============================================================================
	    'Load CSV File to JMP & optionally run a JSL Script
	    '
	    'Args:
	    '====
	    'B1       : Work File - deleted @end of job
	    'MyCSVFile: CSV File to Import
	    'JMPFile  : JMP File to Save Results to [Default = SQLPathFinder.jmp in def folder]
	    '           or opt. Path to JSL to run [Default = NONE].
	    'LeaveJMPOpen: Y to leave JMP open after execution. Interactive use only
	    'MyLocal  : N => use SPF lib, else use local exe dir
	    '=============================================================================
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)

        self.Console("Starting JMP Applet ... v3.4 {0}".format(self.DatetimeNow))
        self.logger.info("{0} - B1: {1}".format(calling_func,B1))
        self.logger.info("{0} - MyCSVFile: {1}".format(calling_func,MyCSVFile))
        self.logger.info("{0} - JMPFile: {1}".format(calling_func,JMPFile))
        self.logger.info("{0} - LeaveJMPOpen: {1}".format(calling_func,LeaveJMPOpen))
        self.logger.info("{0} - MyLocal: {1}".format(calling_func,MyLocal))

        DoCloseJMP = True #"Y" 'Close JMP
        RunJSLFile = False
        JMPObj = None

        try :
            if self.IsEmptyOrNone(JMPFile) == True :
                JMPFile = "SQLPathFinder.jmp"            

            JMPFile_NamePart, JMPFile_ExtPart = os.path.splitext(JMPFile)
            self.logger.info("{0} - JMPFile_NamePart: {1}".format(calling_func,JMPFile_NamePart))
            self.logger.info("{0} - JMPFile_ExtPart: {1}".format(calling_func,JMPFile_ExtPart))

            if self.IsEmptyOrNone(MyCSVFile) == True or self.IsEmptyOrNone(JMPFile) == True :
                errMsg = ("Some input arguments are missing...\n"
                          "CSV File ={0}, JMP File ={1}").format(MyCSVFile, JMPFile)
                raise Exception(errMsg)
            elif MyCSVFile.strip().upper() == "NONE" :
                if JMPFile_ExtPart.upper() == ".JSL" :
                    self.LoadJSL(JMPFile, LeaveJMPOpen, MyLocal)
                    return
                else :
                    errMsg = "Invalid JSL script passed to job:".format(JMPFile)
                    self.gMyAbort = True
                    raise Exception(errMsg) 
            else : 
                """
	            '*********************************
	            'Get Path of JMP/JSL O/P & CSV I/P
	            '*********************************
                """
                MyCSVFile = os.path.abspath(MyCSVFile)
                JMPFile = os.path.abspath(JMPFile)
                self.logger.info("{0} - MyCSVFile: {1}".format(calling_func,MyCSVFile))
                self.logger.info("{0} - JMPFile: {1}".format(calling_func,JMPFile))

                MyCSVFile_Path, MyCSVFile_FileNamePart = os.path.split(MyCSVFile)
                self.logger.info("{0} - MyCSVFile_Path: {1}".format(calling_func,MyCSVFile_Path))

                MyDefDir = ".\\"
                if self.IsEmptyOrNone(MyCSVFile_Path) is False :
                    MyDefDir = MyCSVFile_Path

            if JMPFile_ExtPart.upper() == ".JSL" : # 'JSL File to Run
                """
		        '=====================================================
		        'Test for Existence of RunJSLFile if Arg was specified
		        '=====================================================
                """
                RunJSLFile = True
                if os.path.exists(JMPFile) == False :
                    errMsg = ""
                    self.gMyAbort = True
                    raise Exception(errMsg) 
            else : # 'Will save CSV to JMP
                RunJSLFile = False

            self.logger.info("{0} - RunJSLFile: {1}".format(calling_func,RunJSLFile))

            JSLFile = os.path.abspath(B1)
            self.logger.info("{0} - JSLFile: {1}".format(calling_func,JSLFile))

            """
	        '============
	        'Test for Dlm
	        '============
            """
            DLM00 = self.GetFileDLM(MyCSVFile)
            DT = "Tab, Comma"
            if DLM00 == "\t" :
                DT = "Tab"
            elif DLM00 == "," :
                DT = "Comma"

            self.logger.info("{0} - DT: {1}".format(calling_func,DT))

            L1 = 'csv1 = open("{0}",Import Settings(End Of Line( CRLF, CR, LF ),End Of Field({1}),Strip Quotes( 1 ),Use Apostrophe as Quotation Mark( 0 ),Labels( 1 ),Column Names Start( 1 ),Data Starts( 2 ),Lines To Read( All )));'.format(MyCSVFile, DT)
            self.logger.info("{0} - L1: {1}".format(calling_func,L1))

            if RunJSLFile == False : #'Save CSV to JMP
                createFileCommand = '{0}\ncsv1 << Save("{1}");\nclose(csv1, NoSave);'.format(L1, JMPFile)
                #self.logger.info("{0} - createFileCommand: {1}".format(calling_func, createFileCommand))
                #self.DoCreateFileA(JSLFile, createFileCommand, "LoadJMP")
            else : #'RunJSLFile
                MyDefDir = os.path.abspath(MyDefDir)
                L2 = 'DEFAULT_DIR="{0}";set default directory (::DEFAULT_DIR);'.format("{0}\\".format(MyDefDir) if MyDefDir[-1] != "\\" else MyDefDir)
                self.Console("   The following JSL Code will be executed before your script ...\n     {0}\n".format(L2)) 
                createFileCommand = "{0}\n{1}".format(L1, L2)

            self.logger.info("{0} - createFileCommand: {1}".format(calling_func, createFileCommand))
            self.DoCreateFileA(JSLFile, createFileCommand, "LoadJMP")
            JMPObj, DoCloseJMP = self.StartJMP(MyLocal, LeaveJMPOpen)

            if RunJSLFile == False :
                consMsg = "   Creating JMP Dataset {0} from {1}".format(JMPFile, MyCSVFile)
            else :
                consMsg = "   Loading ... {0}".format(MyCSVFile)
            self.Console(consMsg)

            #'Load the CSV File to JMP
            JMPObj.RunJSLFile(JSLFile) 

            """
	        '===================
	        'Opt. Run JSL Script
	        '===================
            """
            if RunJSLFile == True :
                self.Console("   Running Script ... {0}".format(JMPFile))
                #'Run the User Script
                JMPObj.RunJSLFile(JMPFile)  
                self.LogJMP(JMPObj)
            """
            '********************************
	        'For interact., if JMP open or usr
	        'wants leave JMP open, ~ close JMP
	        '********************************
            """
            if DoCloseJMP == True :
                if not JMPObj is None :
                    JMPObj.quit()
                    time.sleep(2) #need to give time for JMP to close completely else image file auto naming counters get's corrupted. Very rare occurances but this is the only way to handle this
                    self.logger.info("{0} - quit JMP : Ok".format(calling_func))
                    JMPObj = None

        except Exception as err: 
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            self.gMyAbort = True
            raise

    def LoadJSL(self, JMPFile, LeaveJMPOpen, MyLocal) :
        """
        '============================================================================
        'Run JSL Script
        '
        'Args:
        '====
        'JMPFile     : JSL file to run
        'LeaveJMPOpen: Y if JMP should be left open after the execution for interactive use only
        'MyLocal     : N if this is a remote query & job should use the SPF lib, or local exe dir
        '=============================================================================
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)

        self.logger.info("{0} - JMPFile: {1}".format(calling_func,JMPFile))
        self.logger.info("{0} - LeaveJMPOpen: {1}".format(calling_func,LeaveJMPOpen))
        self.logger.info("{0} - MyLocal: {1}".format(calling_func,MyLocal))
        JMPObj = None
        DoCloseJMP = True
        MyDefDir = os.path.abspath('.')
        try :
            JMPFile = os.path.abspath(JMPFile)
            if os.path.exists(JMPFile) == False :
                errMsg = "Could not locate JSL Script passed to job: {0}".format(JMPFile)
                raise Exception(errMsg)

            #use same method to create/get instance of JMP COM object in both Interactive and SH run mode
            JMPObj, DoCloseJMP = self.StartJMP(MyLocal, LeaveJMPOpen)

            L2 = 'DEFAULT_DIR="{0}";set default directory (::DEFAULT_DIR);'.format("{0}\\".format(MyDefDir) if MyDefDir[-1] != "\\" else MyDefDir)
            self.Console("   The following JSL Code will be executed before your script ...\n     {0}\n".format(L2))
            JMPObj.RunCommand(L2) #'set def dir 
            self.Console("   Running Script ... {0}".format(JMPFile))
            JMPObj.RunJSLFile(JMPFile)
            self.LogJMP(JMPObj)
            if DoCloseJMP == True :
                if not JMPObj is None :
                    JMPObj.quit()
                    time.sleep(2) #need to give time for JMP to close completely else image file auto naming counters get's corrupted. Very rare occurances but this is the only way to handle this
            JMPObj = None
            self.ConsoleDoneWithTimeStamp()
        except Exception as err: 
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            self.gMyAbort = True
            raise
    #END : def LoadJSL

    def LogJMP(self, JMPObject) : 
        """
        ' Display contents of JMP log contents to console
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)

        try: 
            #self.Console(JMPObject.HasRunCommandErrorString)
            #if JMPObject.HasRunCommandErrorString is True:
            #    self.Console("Error occured : {0}".format(JMPObject.GetRunCommandErrorString))
            #self.Console("Error occured : {0}".format(JMPObject.GetRunCommandErrorString))
            self.Cons80()
            self.Console("JMP Log")
            self.Cons80()
            self.Console(JMPObject.GetLogContents)
            self.Cons80()
        except Exception as err: 
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            pass #dont raise error
    #END : def LogJMP
#END : class LoadJMPTask

