class RunRFileTask(SPFTaskBase) :
    def __init__(self, SPFTaskItemIn=None, SPFTaskItemIdxIn=None):
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        super(RunRFileTask, self).__init__(SPFTaskItemIn, SPFTaskItemIdxIn)
        self.logger.debug("{0} - RunRFileTask Initialized".format(calling_func))
        return None

    def executeTaskCommand(self):
        r"""
        ' Overridden base method, implementation of Run_R
        '================================
        'Runs R on Windows or Linux
        '================================
        sample input line: /UTILITIES=@EXEDIR@\Run_R_Script.va "testRScript.R" "" "N" "ATD_ATM.HADOOP"
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        MyMode = "F"
        Command1 = None
        MyArgs = None
        MyOS = "W"
        ll_AppSvr = ""
        MyShowSQL = False #"N"
        MyShowOut = False #"N"

        try :
            self.Write_Prompt()
            NoArgs = 0 # number of Args expected to process this Task
            Command1 = self.MyUtilities[1]
            self.logger.info("{0} - Command1: {1}".format(calling_func,Command1))

            try : 
                MyArgs = self.MyUtilities[2]
            except Exception as err: 
                pass #continue with default value: None
            self.logger.info("{0} - MyArgs: {1}".format(calling_func,MyArgs))

            try : 
                Arg5 = self.MyUtilities[3]
                if Arg5 == "Y" :
                    MyOS = "L"
            except Exception as err: 
                pass #continue with default value: "W"
            self.logger.info("{0} - MyOS: {1}".format(calling_func,MyOS))

            try : 
                ll_AppSvr = self.MyUtilities[4]
            except Exception as err: 
                pass #continue with default value: ""
            self.logger.info("{0} - ll_AppSvr: {1}".format(calling_func,ll_AppSvr))

            return self.Run_R(MyMode, Command1, self.gMyLocal, ".\\", ll_AppSvr, False, False, MyArgs, MyOS)

        except Exception as err: 
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise
    #END : def executeTaskCommand
#END : class RunRFileTask

