class RunRScriptTask(SPFTaskBase) :
    def __init__(self, SPFTaskItemIn=None, SPFTaskItemIdxIn=None):
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        super(RunRScriptTask, self).__init__(SPFTaskItemIn, SPFTaskItemIdxIn)
        self.logger.debug("{0} - RunRScriptTask Initialized".format(calling_func))
        return None

    def executeTaskCommand(self):
        """
        ' Overridden base method, implementation of Run_R Mode = S 
        '================================
        'Runs R on Windows or Linux
        '================================
        sample input line: 
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        MyMode = "S"
        Command1 = None
        MyArgs = None
        #MyOS = "W"
        #ll_AppSvr = ""
        MyShowSQL = False #"N"
        MyShowOut = False #"N"

        try :
            self.Write_Prompt()
            NoArgs = 0 # number of Args expected to process this Task

            Command1 = self.SPFTaskCommand
            if self.IsEmptyOrNone(Command1) is True :
                errMsg = "No R script to execute"
                raise Exception(errMsg)

            try : 
                MyArgs = self.MyUtilities[2]
            except Exception as err: 
                pass #continue with default value: None
            self.logger.info("{0} - MyArgs: {1}".format(calling_func,MyArgs))

            try : 
                Arg5 = self.MyUtilities[3]
                if Arg5 == "Y" :
                    self.MyOS = "L"
            except Exception as err: 
                pass #continue with default value: "W" or what was read from /OPSYS
                
            self.logger.info("{0} - MyOS: {1}".format(calling_func,self.MyOS))

            try : 
                self.ll_AppSvr = self.MyUtilities[4]
            except Exception as err: 
                pass #continue with default value: "" or what was read from /APP_SERVER_DEFAULT
            self.logger.info("{0} - ll_AppSvr: {1}".format(calling_func,self.ll_AppSvr))
            self.Record_SPF("r", self.gMyLocal, self.gMyEXEDir, self.gSPFInstance)
            return self.Run_R(MyMode, Command1, self.gMyLocal, ".\\", self.ll_AppSvr, False, False, MyArgs, self.MyOS)

        except Exception as err: 
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
