    #END : def executeTaskCommand
#END : class RunRScriptTask

#status : dev done, UT done
class AppendFileTask(SPFTaskBase) :
    def __init__(self, SPFTaskItemIn=None, SPFTaskItemIdxIn=None):
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        super(AppendFileTask, self).__init__(SPFTaskItemIn, SPFTaskItemIdxIn)
        self.logger.debug("{0} - AppendFileTask Initialized".format(calling_func))
        return None

    def executeTaskCommand(self):
        r"""
        ' Overridden base method. Implementation of SPFMultiAppendFile
        '=========================================================
        'Appends 1 file or files matching a patetrn to another & potentially 
        'limits rows in final file.
        '
        'Args:
        '====
        'File to Add Rows to
        'File or files matching a pattern to Append to first file 
        'Max Rows allowed in 1st file, or -1  for no limit
        '=========================================================
        sample input line: /UTILITIES=@EXEDIR@\AppendFile.va "AppendFileDest.csv" "AppendFileSrc.csv" ""
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        NoArgs = 2 # number of Args expected to process this Task
        MyUtilityName = "APPENDFILE"
        destFile = None #MyInFile1
        srcFile = None #MyInFile2
        MyRows = ""
        errMsg = ""


        try :
            self.Write_Prompt()
            self.Console("Starting Multi-Append Applet, v1.1 .... {0}\n".format(self.DatetimeNow))

            destFile = self.MyUtilities[1]
            self.logger.debug("{0} - MyInFile1 : {1}".format(calling_func, destFile))
            destFile = os.path.abspath(destFile)
            destFile_Path, destFile_Name = os.path.split(destFile)
            self.logger.debug("{0} - destFile_Path : {1}".format(calling_func, destFile_Path))
            self.logger.debug("{0} - destFile_Name : {1}".format(calling_func, destFile_Name))
                
            srcFile = self.MyUtilities[2]
            self.logger.debug("{0} - MyInFile2 : {1}".format(calling_func, srcFile))
            srcFile = os.path.abspath(srcFile)
            srcFile_Path, srcFile_Name = os.path.split(srcFile)
            self.logger.debug("{0} - srcFile_Path : {1}".format(calling_func, srcFile_Path))
            self.logger.debug("{0} - srcFile_Name : {1}".format(calling_func, srcFile_Name))
            try:
                MyRows = self.MyUtilities[3].upper()
            except Exception as err:
                self.logger.warn("{0} - Max Rows parameter not found, continue with default value : '{1}'".format(calling_func, MyRows))

            self.logger.debug("{0} - MyRows : {1}".format(calling_func, MyRows))

            if self.IsEmptyOrNone(destFile) is True or self.IsEmptyOrNone(srcFile) is True :
                errMsg = ("Some of the Source files are missing...\n"
                         "File to add rows to = {0} Source File = {1} Max Rows = {2}").format(destFile, srcFile, MyRows)
                raise Exception(errMsg)

            
            if MyRows.isdigit() is True :
                MyRows = int(MyRows)
            else : 
                MyRows = -1
            self.logger.debug("{0} - MyRows : {1}".format(calling_func, MyRows))           

            if os.path.exists(destFile_Path) is False :
                errMsg = "Sorry, but output folder does not exist: {0}\n".format(destFile_Path)
                raise Exception(errMsg)

            try :
                hasRows  = self.getRowCountFromFile(destFile,countLimit=1) #min 1 row should exist to append...else just overwrite
            except Exception as err: 
                # will error out if dest file doesn't exist
                self.logger.warn("{0} - Destination file doesn't exist, continue with hasRows = 0".format(calling_func))
                hasRows = -1 

            destFileExists = False
            if hasRows >= 0 :
                destFileExists = True
                
            if srcFile_Name.find('*') == -1 : #'No File Ptn
                self.SPFAppendFile(destFile, srcFile, MyRows, destFileExists)
            else : #'File Ptn
                if os.path.exists(srcFile_Path) is False :
                    errMsg = "Sorry, but the source folder does not exist: {0}\n".format(srcFile_Path)
                    raise Exception(errMsg)

                self.Console("Source Folder: {0}".format(srcFile_Path))
                allSrcFilesMatchingPattern = glob.glob(srcFile)

                for srcFileFound in allSrcFilesMatchingPattern :
                    self.SPFAppendFile(destFile, srcFileFound, MyRows, destFileExists)
                    if os.path.exists(destFile) :
                        destFileExists = True

                if len(allSrcFilesMatchingPattern) == 0 :
                    self.Cons80()
                    self.Console("Note that no files matched the requested pattern for appending: {0}".format(srcFile_Name))
                    self.Cons80()
            self.ConsoleDoneWithTimeStamp2()
        except Exception as err: 
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise
#END : class AppendFileTask

