class PyScriptTask(SPFTaskBase) :
    def __init__(self, SPFTaskItemIn=None, SPFTaskItemIdxIn=None):
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        super(self.__class__, self).__init__(SPFTaskItemIn, SPFTaskItemIdxIn)
        self.logger.debug("{0} - {1} Initialized".format(calling_func, self.__class__.__name__))
        return None

    def executeTaskCommand(self):
        """
        ' Overridden base method. PyEE specific task/utility
        '================================
        'Runs Python script on Windows
        '================================
        sample input line: /UTILITIES={PYSCRIPT:IDEAL-TABLE-CONFIG} "mypythonscript.py"  "arg1" "arg2"
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        NoArgs = 2 # number of Args expected to process this Task
        MyUtilityName = "PYSCRIPT"

        Command1 = None # MyArgList(0) 
        MyArgs = None 
        MyOS = "W" 
        ll_AppSvr = None 
        l_WhichPy = "C" if isPYTHON2 is True else "C3" # will use the same python current script is running on
        Arg7 = ""
        try :
            self.Write_Prompt()
            self.Record_SPF(self.MyUtilities[0].strip('{}').replace('PYSCRIPT:',''), self.gMyLocal, self.gMyEXEDir, self.gSPFInstance)
            Command1 = os.path.join(self.gSPFPyEEPath, self.MyUtilities[1])
            self.logger.debug("{0} - Command1 : {1}".format(calling_func, Command1))
            
            if (self.MyUtilities[1].upper() == "AutoCommonalitySPFUtility.py".upper()):
                self.RunAutoCommonalitySPFUtility(self.MyUtilities[2:], Command1)
            else:
                MyArgs = self.MyUtilities[2:] + ["/SPFLOGLEVEL={0}".format(self.parseCMDArgsToken(self.gCommandLineArguments, "/SPFLOGLEVEL", defaultTokenValue="ERROR"))]
                self.logger.debug("{0} - MyArgs : {1}".format(calling_func, MyArgs))
                MyArgs = [item if item.find(' ') == -1 else '"{item}"'.format(item=item) for item in MyArgs]
                self.logger.debug("{0} - updated MyArgs : {1}".format(calling_func, MyArgs))
                self.logger.debug("{0} - l_WhichPy : {1}".format(calling_func, l_WhichPy))
                try:
                    self.Run_Python(Command1, MyArgs, MyOS, self.gMyLocal, self.gSPFInstance, ll_AppSvr, l_WhichPy)
                except Exception as err:
                    if len(err.args) > 1:
                        exitCode = err.args[1]
                        if exitCode == 1:
                            self.logger.warn("{0} - exitCode: {1} ...abort".format(calling_func, exitCode))
                            raise
                        elif exitCode == 2:
                            self.logger.warn("{0} - exitCode: {1} ...continue without abort".format(calling_func, exitCode))
                            self.gMyAbort = False #-- continue dont raise error
                    else:
                        raise #something went wrong even before invoking the external py script...raise err
            #END : if (self.MyUtilities[1].upper() == "AutoCommonalitySPFUtility.py".upper()):
                   
            self.ConsoleDoneWithTimeStamp2()
        except Exception as err: 
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise         
        
    def RunAutoCommonalitySPFUtility(self, MyArgs, PyScriptPath):
        """
        Inproc Execution of {PYSCRIPT:AUTO-COMMONALITY} "AutoCommonalitySPFUtility.py"
        """
        #region locals
        __version = "1.0.0.0"
        input_args = {}
        PyScriptPath = Path(PyScriptPath)
        self.Console
        #endregion locals

        #region logger object
        import logging
        logger = logging.getLogger(__name__)
        logger.setLevel(logging.INFO)
        formatter = logging.Formatter('%(message)s')
        logging_handler = logging.StreamHandler()
        logging_handler.setFormatter(formatter)
        logger.addHandler(logging_handler)
        #endregion logger object

        self.logger.debug(f"PYSCRIPT InProc mode; len(MyArgs) : '{len(MyArgs)}'; PyScriptPath : '{PyScriptPath}';Exists: {PyScriptPath.exists()}")

        #region build input_dict
        try:
            input_args['data_file'] = MyArgs[0]
        except Exception as err:
            self.logger.error(err)
            raise Exception(f"Unable to get 'CSV File to load to Ideal' parameter value", err)

        try:
            input_args['var_conf'] = MyArgs[1]
        except Exception as err:
            self.logger.error(err)
            raise Exception(f"Unable to get 'Variable configuration file' parameter value", err)

        try:
            input_args['out_ide'] =  MyArgs[2]
        except Exception as err:
            self.logger.error(err)
            raise Exception(f"Unable to get 'Ideal Output Specification File' parameter value", err)

        try:
            input_args['report_name'] =  MyArgs[3]
        except Exception as err:
            self.logger.error(err)
            raise Exception(f"Unable to get 'HTML Output File' parameter value", err)

        try:
            input_args['data_origin'] =  MyArgs[4]
        except Exception as err:
            self.logger.error(err)
            raise Exception(f"Unable to get 'Data Type' parameter value", err)

        try:
            input_args['min_importance'] =  MyArgs[5]
        except Exception as err:
            self.logger.error(err)
            raise Exception(f"Unable to get 'Minimum variable importance' parameter value", err)

        try:
            input_args['ini_file'] =  MyArgs[6]
        except Exception as err:
            self.logger.error(err)
            raise Exception(f"Unable to get 'Algorithm' parameter value", err)

        try:
            input_args['imp_var_file'] =  MyArgs[7]
        except Exception as err:
            self.logger.error(err)
            raise Exception(f"Unable to get 'Algorithm' parameter value", err)

        try:
            input_args['model'] =  MyArgs[8]
        except Exception as err:
            self.logger.error(err)
            raise Exception(f"Unable to get 'Algorithm' parameter value", err)

        if (len(MyArgs) > 10):
            try:
                input_args['id_column'] =  MyArgs[9]
            except Exception as err:
                self.logger.error(err)
                raise Exception(f"Unable to get 'Instance' parameter value", err)

            try:
                input_args['response_operation'] =  MyArgs[10]
            except Exception as err:
                self.logger.error(err)
                raise

        try:
            input_args['my_instance'] =  MyArgs[-1]
        except Exception as err:
            self.logger.error(err)
            raise Exception(f"Unable to get 'Instance' parameter value", err)

        try:
            input_args['open_browser'] = True if self.gIsSvc == False else False
        except Exception as err:
            self.logger.error(err)
            raise

        self.logger.debug(f"input_args : {input_args}")
        #endregion build input_dict
        if self.gSPFExe not in sys.path:
            sys.path.insert(1, self.gSPFExe)
            self.logger.debug(f"Added script path to sys.path : {self.gSPFExe}")
        else:
            self.logger.debug(f"Path already exists in sys.path : {self.gSPFExe}")
        import AutoCommonalitySPFUtility
        self.logger.debug("Import done. Begin invoke")
        from AutoCommonalitySPFUtility import Screen_and_Visualize_Features

        try:
            Screen_and_Visualize_Features(input_args, interactive_run = True if self.gIsSvc == False else False, logger=logger)
        except Exception as err:
            self.logger.error(err)
            raise

#END : class PyScriptTask

