class CSVToXMLTask(SPFTaskBase) :
    def __init__(self, SPFTaskItemIn=None, SPFTaskItemIdxIn=None):
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        super(CSVToXMLTask, self).__init__(SPFTaskItemIn, SPFTaskItemIdxIn)
        self.logger.debug("{0} - CSVToXMLTask Initialized".format(calling_func))
        return None

    def executeTaskCommand(self):
        r"""
        ' Overridden base method. Implementation of CSVTOXML.VA -- CSVToXML()
        '================================
        'Convert CSV File to XML
        '
        'Args:
        '====
        'MyCSVFile   : CSV File to convert
        'MyXMLFile   : XML to create [Def=SQLPathFinder.xml]
        'MyStyleSheet: Opt. XSL Style Sheet to format XML File
        '===================================================
        '================================
        sample input line: /UTILITIES=@EXEDIR@\Get_Aqua.va "dmitryg\SKL_SORT_CLASS" "AquaTest2.tab"
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        NoArgs = 2 # number of Args expected to process this Task
        MyUtilityName = "CSVTOXML"
        itemColName = 'Item'

        objXML = None

        MyCSVFile = None # MyArgList(0) 
        MyXMLFile = None # MyArgList(1)
        MyStyleSheet = None # MyArgList(2)
        try :
            self.Write_Prompt()
            self.Console("Starting CSV to XML Applet, v2.2 ... {0}\n".format(self.DatetimeNow))

            MyCSVFile = self.MyUtilities[1]
            MyXMLFile = self.MyUtilities[2]
            MyStyleSheet = self.MyUtilities[3]

            if self.IsEmptyOrNone(MyXMLFile) is True :
                MyXMLFile = "SQLPathFinder.xml"
            
            MyCSVFile = self.Substitute_Std_Tokens(MyCSVFile,"1")
            MyXMLFile = self.Substitute_Std_Tokens(MyXMLFile,"1")

            self.Console("  CSV File to Load   : {0}".format(MyCSVFile))
            self.Console("  XML File to Create : {0}".format(MyXMLFile)) 
            self.Console("  XSL Style Sheet    : {0}".format(MyStyleSheet))
            
            if self.IsEmptyOrNone(MyCSVFile) is True :
                self.Cons80()
                self.Console("Some input arguments are missing. Exiting ...")
                self.Console("CSV File    = {0}".format(MyCSVFile))
                self.Console("XML File    = {0}".format(MyXMLFile)) 
                self.Console("Style Sheet = {0}".format(MyStyleSheet))
                self.Cons80()
                #dont raise error?
                return

            """
            '*********************************
            'Get Path of CSV i/p & XL o/p File
            '*********************************
            """
            MyXMLFile = os.path.abspath(MyXMLFile)
            MyCSVFile = os.path.abspath(MyCSVFile)
            self.logger.debug("{0} - MyXMLFile : {1}".format(calling_func, MyXMLFile))
            self.logger.debug("{0} - MyCSVFile : {1}".format(calling_func, MyCSVFile))
            """
            '******************************
            'Extract Folder from Dest. Path
            '******************************
            """
            MyXMLFile_Path, MyXMLFile_FileName = os.path.split(MyXMLFile)
            self.logger.debug("{0} - MyXMLFile_Path : {1}".format(calling_func, MyXMLFile_Path))
            self.logger.debug("{0} - MyXMLFile_FileName : {1}".format(calling_func, MyXMLFile_FileName))

            if self.IsEmptyOrNone(MyXMLFile_Path) is True :
                MyXMLFile_Path = ".\\"

            if os.path.exists(MyCSVFile) is False :
                errMsg = "\nSorry, but could not locate CSV file:\n {0}\n".format(MyCSVFile)
                raise Exception(errMsg)

            if os.path.exists(MyXMLFile_Path) is False :
                errMsg = "\nSorry, but destination directory for XML file does not exist:\n {0}\n".format(MyXMLFile_Path)
                raise Exception(errMsg)

            if os.path.exists(MyXMLFile) is True :
                try: 
                    self.SPFDelete(MyXMLFile)
                except Exception as err: 
                    self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
                    errMsg = ("{0}  occurred while accessing {1}\n"
                              "You do not have permissions to overwrite this file."
                              ).format(err.args[0], MyCSVFile)
                    raise Exception(errMsg)

            """
            '************
            'Get delimiter
            '************
            """
            l_DLM = self.GetFileDLM(MyCSVFile)
            self.logger.debug("{0} - l_DLM : {1}".format(calling_func, l_DLM))

            try :
                objXML = xmlMiniDomDocument()
                objRoot = objXML.createElement("Main")
                objRoot.setAttribute("Created", self.DatetimeNow)
                objRoot.setAttribute("Source", MyCSVFile)

                if self.IsEmptyOrNone(MyStyleSheet) is False : 
                    pi1 = objXML.createProcessingInstruction("xml-stylesheet",'type="text/xsl" href="{0}"'.format(MyStyleSheet))
                    objXML.appendChild(pi1)
                objXML.appendChild(objRoot)
                #self.logger.debug("{0} - objXML : {1}".format(calling_func, objXML.toprettyxml("utf-8")))
            except Exception as err: 
                self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
                errMsg = "The following error occurred while initializing XML DOM Document object: \n{0}\n".format(err.args[0])
                raise Exception(errMsg)
            
            tmpstring =  objXML.toxml()
            #with open(MyXMLFile, "w") as xmlFileToWrite :
            with codecs.open(MyXMLFile, "w", encoding='UTF-8', errors='escape') as xmlFileToWrite: #XML standard to use UTF-8
                #objXML.writexml(xmlFileToWrite, encoding="utf-8")
                #rootXML = "{0}>\n".format(objXML.toprettyxml("utf-8")[:-3]) # -- has issues on SH LF+spaces around values
                rootXML = "{0}>".format(tmpstring[:-2].replace("?>", "?>\n"))
                self.logger.debug("{0} - rootXML : {1}".format(calling_func, rootXML))
                xmlFileToWrite.write(rootXML)

            #raise Exception("err test")
            try : 
                #txtNodeCreator = lambda x : objXML.createTextNode(x.strip() if self.IsEmptyOrNone(x) is False else ".")
                txtNodeCreator = lambda x : x.strip() if not x in ["", None] else "."
                
                allColsList = self.GetHeadersFromFile(MyCSVFile, l_DLM)
                #'Remove Special Chars from hdr (Columns)
                allColsList = [re.sub(r"[^\d\w__]", "_", colItem, re.IGNORECASE|re.VERBOSE) for colItem in allColsList]
                self.logger.debug("{0} - allColsList : {1}".format(calling_func, allColsList))
                #allColsXMLElementList_tmp = [objXML.createElement(colItem) for colItem in allColsList]
                converter = dict((colItem,txtNodeCreator) for colItem in allColsList )
                #self.logger.debug("{0} - converter : {1}".format(calling_func, converter)) 
                with codecs.open(MyCSVFile, "r", encoding=self.gOSDefaultEncoding, errors='replace') as MyCSVFileRdr:
                    with codecs.open(MyXMLFile, "a", encoding="UTF-8", errors='replace') as xmlFileToWrite: #XML standard to use UTF-8
                        if isPYTHON2:
                            dfReader = pd.read_csv(filepath_or_buffer=MyCSVFileRdr, sep=l_DLM, na_filter=False, iterator=True, chunksize=1000, names=allColsList, header=0, converters=converter)#, encoding=sys.getfilesystemencoding()
                        else:
                            dfReader = pd.read_csv(filepath_or_buffer=MyCSVFileRdr, sep=l_DLM, na_filter=False, iterator=True, chunksize=1000, names=allColsList, header=0, converters=converter)#, encoding=self.gOSDefaultEncoding)
                        for dfItem in dfReader:
                            for colitem in allColsList:
                                dfItem[colitem] =  dfItem[colitem].apply(lambda x: "<{0}>{1}</{0}>".format(colitem, escape(str(x))))
                            dfItem[itemColName] = dfItem.apply("".join, axis=1).apply(lambda x: "<{0}>{1}</{0}>".format(itemColName, x))
                            dfItem.drop(labels=dfItem.columns.difference([itemColName]),axis=1, inplace=True)
                            for valItem in dfItem.values:
                                if isPYTHON2 is True:
                                    try:
                                        xmlFileToWrite.write("".join(valItem))
                                    except UnicodeDecodeError as decodingErr:
                                        self.logger.exception("{0} - {1}".format(calling_func, decodingErr))
                                        errMsg = "The following error occurred : \n{0}\n{1}\n{2}\n...retry with encoding".format(decodingErr, decodingErr.object, decodingErr.start)
                                        xmlFileToWrite.write("".join(valItem).decode('utf-8', errors='replace'))
                                else:
                                    xmlFileToWrite.write("".join(valItem))
                        xmlFileToWrite.write("</Main>\n") #write end root element 
                #below is old code...changed to handle memory leak
                #with open(MyXMLFile, "w") as xmlFileToWrite :
                #    objXML.writexml(xmlFileToWrite, encoding="utf-8")
            except UnicodeDecodeError as decodingErr:
                self.logger.exception("{0} - {1}".format(calling_func, decodingErr))
                errMsg = "The following error occurred : \n{0}\n{1}\n{2}\n...retry with encoding".format(decodingErr, decodingErr.object, decodingErr.start)
                raise Exception(errMsg)
            except Exception as err : 
                self.logger.exception("{0} - {1}".format(calling_func, err))
                errMsg = "The following error occurred : \n{0}\n".format(err.args[0])
                raise Exception(errMsg)

            self.ConsoleDoneWithTimeStamp2()
        except Exception as err : 
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise
        finally : 
            if not objXML is None :
                objXML.unlink()
                objXML = None
#END : class CSVToXMLTask

