class CSVToHTMLTask(SPFTaskBase) :
    def __init__(self, SPFTaskItemIn=None, SPFTaskItemIdxIn=None):
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        super(CSVToHTMLTask, self).__init__(SPFTaskItemIn, SPFTaskItemIdxIn)
        self.logger.debug("{0} - CSVToHTMLTask Initialized".format(calling_func))
        return None

    def executeTaskCommand(self):
        r"""
        ' Overridden base method. Implementation of CSVTOHTML.VA -- CSVToHTMLTask()
        '============================================
        'Convert a CSV File to HTML
        '
        'Args:
        '====
        'MyCSVFile : CSV File
        'MyHTMLFile: HTML File[Def=SQLPathFinder.html]
        'MyHeader  : Opt. HTML Hdr
        '=============================================
        sample input line: /UTILITIES=@EXEDIR@\CSVToHTML.va "CSVToHTMLTask_HT01_Input.CSV" "CSVToHTMLTask_HT01_output.html" "Yahooo Py Generated CSV to HTML Report"
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        NoArgs = 2 # number of Args expected to process this Task
        MyUtilityName = "CSVTOHTML"

        MyCaption = None

        MyCSVFile = None # MyArgList(0) 
        MyHTMLFile = None # MyArgList(1)
        MyHeader = None # MyArgList(2)
        try :
            self.Write_Prompt()
            self.Console("Starting CSV to HTML Applet, v1.1 ... {0}\n".format(self.DatetimeNow))

            MyCSVFile = self.MyUtilities[1]
            MyHTMLFile = self.MyUtilities[2]
            MyHeader = self.MyUtilities[3]

            if self.IsEmptyOrNone(MyHTMLFile) is True :
                MyHTMLFile = "SQLPathFinder.xml"
            
            MyCSVFile = self.Substitute_Std_Tokens(MyCSVFile,"1")
            MyHTMLFile = self.Substitute_Std_Tokens(MyHTMLFile,"1")

            self.Console("  CSV File to Load    : {0}".format(MyCSVFile))
            self.Console("  HTML File to Create : {0}".format(MyHTMLFile)) 
            self.Console("  Header for HTML O/P : {0}".format(MyHeader))
            """
            '***************
            'Perform Err Chk
            '***************
            """
            if self.IsEmptyOrNone(MyCSVFile) is True :
                self.Cons80()
                self.Console("Input CSV File is missing...")
                self.Console("Exiting ...")
                self.Cons80()
                #dont raise error?
                return

            """
            '*********************************
            'Get Path of CSV i/p & XL o/p File
            '*********************************
            """
            MyHTMLFile = os.path.abspath(MyHTMLFile)
            MyCSVFile_withPath = os.path.abspath(MyCSVFile)
            self.logger.debug("{0} - MyXLFile : {1}".format(calling_func, MyHTMLFile))
            self.logger.debug("{0} - MyCSVFile_withPath : {1}".format(calling_func, MyCSVFile_withPath))
            """
            '******************************
            'Extract Folder from Dest. Path
            '******************************
            """
            MyHTMLFile_Path, MyHTMLFile_FileName = os.path.split(MyHTMLFile)
            self.logger.debug("{0} - MyHTMLFile_Path : {1}".format(calling_func, MyHTMLFile_Path))
            self.logger.debug("{0} - MyHTMLFile_FileName : {1}".format(calling_func, MyHTMLFile_FileName))

            if self.IsEmptyOrNone(MyHTMLFile_Path) is True :
                MyHTMLFile_Path = ".\\"

            if os.path.exists(MyCSVFile_withPath) is False :
                errMsg = "\nSorry, but could not locate CSV file:\n {0}\n".format(MyCSVFile_withPath)
                raise Exception(errMsg)

            if os.path.exists(MyHTMLFile_Path) is False :
                errMsg = "\nSorry, but destination directory for HTML file does not exist:\n {0}\n".format(MyHTMLFile)
                raise Exception(errMsg)

            if os.path.exists(MyHTMLFile) is True :
                try: 
                    self.SPFDelete(MyHTMLFile, displayPrompt=False)
                except Exception as err: 
                    self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
                    errMsg = ("{0}  occurred while accessing {1}\n"
                              "You do not have permissions to overwrite this file."
                              ).format(err.args[0], MyHTMLFile)
                    raise Exception(errMsg)

            """
            '************
            'Get delimiter
            '************
            """
            l_DLM = self.GetFileDLM(MyCSVFile)
            self.logger.debug("{0} - l_DLM : {1}".format(calling_func, l_DLM))

            try :
                htmlHeader = ("<html>\n"
                              "<head>\n"
                              "<title>{0}</title>\n"
                              '<style type="text/css">\n'
                              "  table {{\n"
                              "     border: thin solid #cdcdcd;\n"
                              "     border-collapse:collapse;\n"
                              "     caption-side: top;\n"
                              "}}\n"
                              "  td {{border: thin solid #cdcdcd;\n"
                              "      border-collapse:collapse;\n"
                              "      padding: 5px;\n"
                              "      font-family:arial;\n"
                              "      font-size:12;\n"
                              "}}\n"
                              "  th {{background-color : #eee;\n"
                              "      color:#3d3d3d;\n"
                              "      border: thin solid #cdcdcd;\n"
                              "      border-collapse:collapse;\n"
                              "      font-family:arial;\n"
                              "      font-size:12;\n"
                              "      padding: 5px;\n"
                              "      padding-top:5px;\n"
                              "      padding-bottom:4px;\n"
                              "      /*font-size:1.1em;*/\n"
                              "      text-align:left;\n"
                              "}}\n"
                              "  caption {{padding-top: 8px;}}\n"
                              "  tr.alt td {{\n"
                              "     color:#3d3d3d;\n"
                              "     background-color:#ebfaeb;\n"
                              "}}\n"
                              "</style>\n"
                              "</head>\n"
                              "<body>\n"
                              "<table>\n").format(MyCSVFile)

                MyPost = "\n</table>\n</body>\n</html>"

                if self.IsEmptyOrNone(MyHeader) is False : 
                    MyCaption = "\n<caption><h3>{0}</h3></caption>".format(MyHeader)
                self.logger.debug("{0} - MyCaption : {1}".format(calling_func, MyCaption))
                
                #function to embed data into HTML tags
                txtHTMLCreator = lambda x : "    <td>{0}</td>".format(x)
                
                allColsList = self.GetHeadersFromFile(MyCSVFile, l_DLM)
                #'Replace "_" with " " in Columns names
                allColsList = ["    <th>{0}</th>".format(colItem.replace("_", " ")) for colItem in allColsList]
                self.logger.debug("{0} - allColsList : {1}".format(calling_func, allColsList))

                #prep dataframe converter
                converter = dict((colItem,txtHTMLCreator) for colItem in allColsList )
                self.logger.debug("{0} - converter : {1}".format(calling_func, converter)) 

                #write the begining of HTML portions
                with open(MyHTMLFile, "w") if isPYTHON2 is True else open(MyHTMLFile, "w", encoding=self.gOSDefaultEncoding, errors='replace') as htmlToWrite :
                    htmlToWrite.write(htmlHeader)
                    if not MyCaption is None : 
                        htmlToWrite.write(MyCaption)
                    htmlToWrite.write("\n  <tr>\n{0}\n  </tr>\n".format("\n".join(allColsList)))
                
                #now read CSV and start writing in chunks 
                with codecs.open(MyCSVFile, "r", encoding=self.gOSDefaultEncoding, errors='replace') as MyCSVFileRdr:
                    dfReader = pd.read_csv(filepath_or_buffer=MyCSVFileRdr, sep=l_DLM, na_filter=False, chunksize=10000, names=allColsList, header=0, converters=converter)
                    lenOfRowsRead = 0
                    prevLenofRowsRead = 0
                    for dfItem in dfReader :
                        lenOfRowsRead = len(dfItem)

                        #add dummy columns to DF to hold row Start/End HTML tags
                        dfItem.insert(0, "trStart", pd.Series([r"  <tr>" if item1 % 2 == 0 else r"  <tr class ='alt'>" for item1 in range(prevLenofRowsRead,prevLenofRowsRead+lenOfRowsRead)], index=dfItem.index))
                        dfItem["trEnd"] = "  </tr>"

                        #update the rowcount tracker
                        prevLenofRowsRead = prevLenofRowsRead + lenOfRowsRead
                        
                        #write HTML to file
                        with codecs.open(MyHTMLFile, "a", encoding=self.gOSDefaultEncoding, errors='replace') as htmlToWrite :
                            for rows in dfItem.apply("\n".join, axis=1).values:
                                htmlToWrite.write(rows.strip(" "))

                #now write the tail portion of HTML file
                with codecs.open(MyHTMLFile, "a", encoding=self.gOSDefaultEncoding, errors='replace') as htmlToWrite :
                    htmlToWrite.write(MyPost)
                    
            except Exception as err: 
                self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
                errMsg = "The following error occurred : \n{0}\n".format(err.args[0])
                raise Exception(errMsg)

            self.ConsoleDoneWithTimeStamp2()
        except Exception as err: 
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise
#END : class CSVToXMLTask

