class SPFZipTask(SPFTaskBase) :
    def __init__(self, SPFTaskItemIn=None, SPFTaskItemIdxIn=None):
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        super(SPFZipTask, self).__init__(SPFTaskItemIn, SPFTaskItemIdxIn)
        self.logger.debug("{0} - SPFZipTask Initialized".format(calling_func))
        return None
    def executeTaskCommand(self):
        r"""
        ' Overridden base method. Implementation of SPFZIP.VA -- ZipFiles(), ZipFolder
        '========================================================================
        'Zips one or more files and optionally deletes the source files
        '
        'Args:
        '====
        '1) MyCSVFile : Path and name of File(s) to Zip separated by commas or a single folder containing files to zip
        '2) MyZipFile : Path and name of zip file to create
        '3) DoDel     : Y if the source files should be deleted and N otherwise. Default is N
        '4) MyReturn  : Returns 0 if successful and 1 or higher if there was an error
        '========================================================================
        sample input line: /UTILITIES=@EXEDIR@\SPFZIP.va "SPFZipTask_HT01_input.tab" "SPFZipTask_HT01_output.zip" "N"
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        NoArgs = 2 # number of Args expected to process this Task
        MyUtilityName = "SPFZIP"

        MyCSVFile = None # MyArgList(0) 
        MyZipFile = None # MyArgList(1)
        DoDel = "N" # MyArgList(2)
        

        try :
            self.Write_Prompt()
            self.Console("Starting Zip Applet v2.0 ...")
            MyCSVFile = self.MyUtilities[1]
            MyZipFile = self.MyUtilities[2]
            try :
                DoDel = self.MyUtilities[3]
            except Exception as err: 
                self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))

            self.logger.debug("{0} - MyCSVFile: '{1}'".format(calling_func, MyCSVFile))
            self.logger.debug("{0} - MyZipFile: '{1}'".format(calling_func, MyZipFile))
            self.logger.debug("{0} - DoDel: '{1}'".format(calling_func, DoDel))
            """
            '******************
            'Perform Arg Err Chk
            '******************
            """
            DoDel = self.convertYNToBool(DoDel)
            self.logger.debug("{0} - DoDel: '{1}'".format(calling_func, DoDel))

            if self.IsEmptyOrNone(MyZipFile) is True :
                MyZipFile = "SQLPathFinder.zip"
                self.logger.debug("{0} - MyZipFile: '{1}'".format(calling_func, MyZipFile))
            elif Path(MyZipFile).name.lower().endswith('.zip') is False:
                MyZipFile = f"{MyZipFile}.zip"
                self.logger.debug("{0} - Add .zip extension MyZipFile: '{1}'".format(calling_func, MyZipFile))

            if self.IsEmptyOrNone(MyCSVFile) is True :
                errMsg = "No zip files are specified...{0}".format(MyCSVFile)
                raise Exception(errMsg)

            self.Cons80()
            self.Console("Files (or Folder) to Zip = {0}".format(MyCSVFile))
            self.Console("Zip File to create       = {0}".format(MyZipFile))
            self.Console("Delete Source Files?     = {0}".format(DoDel))
            self.Cons80()

            MyZipFile = os.path.abspath(MyZipFile)
            self.logger.debug("{0} - abspath of MyZipFile: '{1}'".format(calling_func, MyZipFile))
            #'===v30.59  ===========
            """
            '=========================
            'Check that you can Write
            'to the ZIP file
            '=========================
            """
            if os.path.exists(MyZipFile) is True :
                try :
                    self.SPFDelete(MyZipFile, displayPrompt=False)
                except Exception as err:
                    self.logger.warn("{0} - {1}".format(calling_func, err.args[0]))
                    try :
                        #file may be RO -- try setting to normal attribute and delete the file
                        win32api.SetFileAttributes(MyZipFile, win32con.FILE_ATTRIBUTE_NORMAL)
                        self.SPFDelete(MyZipFile, displayPrompt=False)
                    except Exception as err:
                        self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
                        errMsg = "ZIP file not writeable: {0}\n{1}\nCheck that file is not locked and that you have write access to output folder".format(MyZipFile, err.args[0])
                        self.gMyAbort = True
                        raise Exception(errMsg)
                     
            #'========================

            """
            '******************************************
            'Determine if files to zip are specified 
            'as a folder or a comma delimited file list,
            '& zip them
            '******************************************
            """
            
            if os.path.isdir(MyCSVFile) is True: #' this is a folder
                self.logger.debug("{0} - processing ZipFolder ".format(calling_func))
                self.ZipFolder2(MyCSVFile, MyZipFile, DoDel)
            else :
                #'Create a File list array, verify each file and zip them
                # MyCSVList = MyCSVFile.split(",")
                mycsvRdr = csv.reader(StringIO(MyCSVFile), delimiter=",", skipinitialspace=True, quotechar='"')
                MyCSVList = next(mycsvRdr)
                MyCSVList_processed = []
                #region - Old code using zip.exe
                # while len(MyCSVList) > 0 :
                #     fileItem = MyCSVList.pop(0).strip()
                #     self.logger.debug("{0} - fileItem: '{1}'".format(calling_func, fileItem))
                #     fileItem = os.path.abspath(fileItem)
                #     self.logger.debug("{0} - fileItem: '{1}'".format(calling_func, fileItem))

                #     if os.path.exists(fileItem) is False :
                #         self.Console("Could not locate one of the zip files. File will be skipped {0}".format(fileItem))
                #     else :
                #         MyCSVList_processed.append('"{0}"'.format(fileItem))
                # self.logger.debug("{0} - MyCSVList_processed: '{1}'".format(calling_func, MyCSVList_processed))
                # MyCSVFile = ' '.join(MyCSVList_processed)
                # self.logger.debug("{0} - MyCSVFile: '{1}'".format(calling_func, MyCSVFile))
                # del MyCSVList_processed
                # self.ZipFiles(MyCSVFile, MyZipFile, DoDel)
                #endregion - Old code using zip.exe

                #region - new using Py Zip 
                while len(MyCSVList) > 0 :
                    fileItem = MyCSVList.pop(0).strip()
                    self.logger.debug("{0} - fileItem: '{1}'".format(calling_func, fileItem))
                    # fileItem = os.path.abspath(fileItem)
                    # self.logger.debug("{0} - fileItem: '{1}'".format(calling_func, fileItem))
                    if os.path.exists(fileItem) is False :
                        self.Console("Could not locate one of the zip files. File will be skipped {0}".format(fileItem))
                    else :
                        MyCSVList_processed.append(fileItem)

                self.logger.debug("{0} - MyCSVList_processed: '{1}'".format(calling_func, MyCSVList_processed))
                self.ZipFiles2(MyCSVList_processed, MyZipFile, DeleteSourceFilesAfterArchiving=DoDel)
                #endregion - new using Py Zip 
            self.ConsoleDoneWithTimeStamp2()
        except Exception as err: 
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise
#END : class SPFZipTask

