class SPFUNZipTask(SPFTaskBase) :
    def __init__(self, SPFTaskItemIn=None, SPFTaskItemIdxIn=None):
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        super(SPFUNZipTask, self).__init__(SPFTaskItemIn, SPFTaskItemIdxIn)
        self.logger.debug("{0} - SPFUNZipTask Initialized".format(calling_func))
        return None
    def executeTaskCommand(self):
        r"""
        ' Overridden base method. Implementation of SPFUNZIP.VA -- UnzipFile()
        '=====================================================================
        'UnZips all files in a zip file to a folder. DoPath determines if you
        'want to unzip the path or to just extract files to the extract folder
        '
        'Args:
        '====
        'MyZipFile: Path of zip file to unzip
        'MyFolder : Extract folder
        'DoPath   : Whether to include source path or to just extract to dest. dir
        'MyLocal  : N for SH run and SPF exe path for interactive run
        '
        'GLOBALS:
        '-------
        'gMyAbort: Y if job should be aborted
        '======================================================================
        sample input line: /UTILITIES=@EXEDIR@\SPFZIP.va "SPFZipTask_HT01_input.tab" "SPFZipTask_HT01_output.zip" "N"
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        NoArgs = 2 # number of Args expected to process this Task
        MyUtilityName = "SPFUNZIP"

        MyZipFile = None # MyArgList(0) 
        MyFolder = None # MyArgList(1)
        DoPath = "N" # MyArgList(2)
        

        try :
            self.Write_Prompt()
            self.Console("Starting UnZip Applet v2.2 ...")
            MyZipFile = self.MyUtilities[1]
            MyFolder = self.MyUtilities[2]
            try :
                DoPath = self.MyUtilities[3]
            except Exception as err: 
                self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))

            self.logger.debug("{0} - MyZipFile: '{1}'".format(calling_func, MyZipFile))
            self.logger.debug("{0} - MyFolder: '{1}'".format(calling_func, MyFolder))
            self.logger.debug("{0} - DoPath: '{1}'".format(calling_func, DoPath))
            """
            '******************
            'Perform Arg Err Chk
            '******************
            """
            DoPath = self.convertYNToBool(DoPath)
            self.logger.debug("{0} - DoPath: '{1}'".format(calling_func, DoPath))

            if self.IsEmptyOrNone(MyZipFile) is True :
                errMsg = "No zip file specified..."
                raise Exception(errMsg)
            MyZipFile = os.path.abspath(MyZipFile)

            if os.path.exists(MyZipFile) is False :
                errMsg = "Zip File does not exist ...\n  {0}".format(MyZipFile)
                raise Exception(errMsg)

            if MyFolder == ".\\" or MyFolder == "\\":
                MyFolder = ""
        
            MyFolder = MyFolder.rstrip("\\")

            if MyFolder != "" :
                if os.path.exists(MyFolder) is False :
                    errMsg = "Extract Folder does not exist ...\n  {0}".format(MyFolder)
                    raise Exception(errMsg)

            self.Cons80()
            self.Console("Zip File            = {0}".format(MyZipFile))
            self.Console("Extract Folder      = {0}".format(MyFolder))
            self.Console("Include Source Path = {0}".format(DoPath))
            self.Cons80()

            self.UnzipFile(MyZipFile, MyFolder, DoPath)
            

            self.ConsoleDoneWithTimeStamp2()
        except Exception as err: 
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            self.gMyAbort = True
            raise
#END : class SPFZipTask

