class DOSCmdTask(SPFTaskBase) :
    def __init__(self, SPFTaskItemIn=None, SPFTaskItemIdxIn=None):
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        super(DOSCmdTask, self).__init__(SPFTaskItemIn, SPFTaskItemIdxIn)
        self.logger.debug("{0} - DOSCmdTask Initialized".format(calling_func))
        return None
    def executeTaskCommand(self):
        """
        ' Overridden base method. Implementation of DOS command execution -- Run_Dos()
        '=================================================
        'Run a DOS Command line
        '
        ' ARGS:
        ' ----
        'MyInstance: SPF Instance #
        'MyJob    : Job to execute
        'RNStr    : Random Number
        'objFSO   : File System Object
        'MyExeDir : Exe Directory with a slash
        'MyLocal  : N for a remote query, else local exe dir
        '=================================================
        sample input line: /UTILITIES=dir ".\"
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        NoArgs = 1 # number of Args expected to process this Task
        MyUtilityName = "Run a dos command"
        DoAbort = False
        MyReturn = 0

        MyFileName = None # MyArgList(0) 
        b1 = ".\\{0}.bat".format(self.RNStrNew)
        b2 = ".\\{0}_2.bat".format(self.RNStrNew)      

        try :
            self.Write_Prompt()
            self.logger.debug("{0} - b1: '{1}'".format(calling_func, b1))
            self.logger.debug("{0} - b2: '{1}'".format(calling_func, b2))

            if self.MyUtilitiesValue.upper().find("[ABORT-IF-EXITCODE]") > -1 :
                DoAbort = True
                self.MyUtilitiesValue = re.sub(r"\[ABORT\-IF\-EXITCODE\]", "", self.MyUtilitiesValue, 0, re.IGNORECASE).strip() #self.MyUtilitiesValue.replace("[ABORT-IF-EXITCODE]", "")
            self.logger.debug("{0} - DoAbort: '{1}'".format(calling_func, DoAbort))
            self.logger.debug("{0} - self.MyUtilities: '{1}'".format(calling_func, self.MyUtilities))
            MyFileName = self.MyUtilities[0]
            self.logger.debug("{0} - MyFileName: '{1}'".format(calling_func, MyFileName))
            
            r"""
            '====================================
            'Replace references to @EXEDIR@ with
            'SPF Exe Dir./ Add quotes around Job
            'in case of spaces c:\1.va "1" to "c:\1.va" "1"
            '=====================================
            """
            if MyFileName.find("@EXEDIR@\\") != -1 :
                MyFileName = MyFileName.replace("@EXEDIR@\\", self.gMyEXEDir)
                self.logger.debug("{0} - MyFileName: '{1}'".format(calling_func, MyFileName))
            if os.path.exists(MyFileName) is True :
                #'...if Job Exists
                MyFileName_NamePart, MyFileName_ExtPart = os.path.splitext(MyFileName)
                self.logger.debug("{0} - MyFileName_NamePart: '{1}'".format(calling_func, MyFileName_NamePart))
                self.logger.debug("{0} - MyFileName_ExtPart: '{1}'".format(calling_func, MyFileName_ExtPart))
                if self.IsEmptyOrNone(MyFileName_ExtPart) is True : 
                    self.Console("Sorry, but job {0} must have an extension. Going on to the next job...".format(MyFileName))
                    return
                if MyFileName_ExtPart.upper() == ".VA" :
                    #'A VA Job
                    self.logger.debug("{0} - running a VA Job".format(calling_func))
                    cmdToExec = "va"
                    cmdArgs = self.MyUtilities
                    runStatus, MyReturn = self.Run(cmdToExec, cmdArgs)
                elif MyFileName_ExtPart.upper() == ".BAT" :
                    #'A BAT Job
                    self.logger.debug("{0} - running a BAT Job".format(calling_func))
                    cmdToExec = "%COMSPEC%"
                    cmdArgs = ["/c"] + self.MyUtilities
                    runStatus, MyReturn = self.Run(cmdToExec, cmdArgs, usePopen=False)
                elif MyFileName_ExtPart.upper() == ".JSL" :
                    #'A JSL Job
                    self.logger.debug("{0} - running a JSL Job".format(calling_func))
                    MyJob = self.MyUtilitiesValue
                    self.logger.debug("{0} - MyJob: '{1}'".format(calling_func, MyJob))
                    
                    self.DoCreateFileA(b2, '"{0}"'.format(MyJob), "Run_DOS")
                    cmdToExec = b2
                    cmdArgs = []
                    runStatus, MyReturn = self.Run(cmdToExec, cmdArgs)
                    time.sleep(2) #'Wait 2s job to start
                else : #'Job does not have an extension
                    self.logger.warn("{0} - running '{1}' an unkown file of ext : {2}".format(calling_func, MyFileName, MyFileName_ExtPart))
                    MyJob = self.MyUtilitiesValue
                    self.logger.debug("{0} - MyJob: '{1}'".format(calling_func, MyJob))
                    self.DoCreateFileA(b1, '{0}'.format(MyJob), "Run_DOS")
                    cmdToExec = b1
                    cmdArgs = []
                    runStatus, MyReturn = self.Run(cmdToExec, cmdArgs)
            else : #'Job does not exist                
                self.logger.debug("{0} - self.MyUtilities[0]: '{1}'".format(calling_func, self.MyUtilities[0]))
                if self.MyUtilities[0] == "va.exe" :
                    #save the file to a temp .va file 
                    tmpVa = ".\\{0}_tmp.va".format(self.RNStr)
                    self.DoCreateFileA(tmpVa, self.unzipString(self.MyUtilities[1]),"Run_DOS")
                    #run the tmp va script
                    cmdToExec = "va"
                    cmdArgs = ['"{0}"'.format(tmpVa)]
                    runStatus, MyReturn = self.Run(cmdToExec, cmdArgs)
                    self.DelAFile(tmpVa)
                else  :
                    cmdToExec = "%COMSPEC%"
                    #cmdArgs = ["/c"] + ['{0}'.format(self.MyUtilitiesValue)]
                    nonBlocking = True if self.MyUtilities[0].upper() == "START" else False
                    temp_bat =  ".\\{0}_tmp.bat".format(self.RNStr)
                    self.DoCreateFileA(temp_bat, self.MyUtilitiesValue,"Run_DOS")
                    cmdArgs = ["/c"] + ['{0}'.format(temp_bat)]
                    #runStatus, MyReturn = self.Run(cmdToExec, cmdArgs, usePopen=False, nonBlocking=True if self.MyUtilities[0].upper() == "START" else False)
                    runStatus, MyReturn = self.Run(cmdToExec, cmdArgs, usePopen=False, nonBlocking=nonBlocking)
                    self.DelAFile(temp_bat)
            self.logger.debug("{0} - MyReturn: '{1}'".format(calling_func, MyReturn))
            if MyReturn != 0 and DoAbort is True : #'Error
                raise Exception("Completed with Exit code : '{0}'".format(MyReturn))
            self.ConsoleDoneWithTimeStamp4()
        except Exception as err:
            try: 
                MyReturn = err[1]
            except Exception as err2:
                MyReturn = -1
            self.logger.exception("{0} - {1}".format(calling_func, err))
            if MyReturn != 0 and DoAbort is True : #'Error
                self.gMyAbort = True
                raise Exception("Completed with Exit code : '{0}'".format(MyReturn))
        finally :
            self.Console()
            self.DelAFile(b1)
#END : class DOSCmdTask

