class MongoExportTask(SPFTaskBase) :
    def __init__(self, SPFTaskItemIn=None, SPFTaskItemIdxIn=None):
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        super(MongoExportTask, self).__init__(SPFTaskItemIn, SPFTaskItemIdxIn)
        self.logger.debug("{0} - MongoExportTask Initialized".format(calling_func))
        return None
    def executeTaskCommand(self):
        r"""
        ' Overridden base method. Implementation of MongoExport() -- 
        '===== v30.52 ==========
        '====================================================
        'Extract t CSV from MongoDB DB
        '
        'Args:
        '====
        'MyLocal: Local Exe Dir or N or ...
        'MyHost : Host and Port to Connect to. Format host:port@un@pw
        'MyDB   : Database
        'MyColl : Collection
        'MyOut  : Output File
        'MyFF   : Field File
        'MyQ    : Query or Query File or Empty
        'MyOther: Other MongoExport Options (e.g., --limit 10 --skip 10 
        '
        'GLOBALS:
        '-------
        'gTempDir    : SPF SW on Drones
        'gLocalDir   : Local Folder
        'gMyAbort    : Job Abort global
        'gSHFolder   : SH Analysis SPF SHare
        '
        '====================================================
        sample input line: /UTILITIES=@EXEDIR@\MongoDB-Export.va "localhost:27017" "cols.cols2" "cols.cols" "mydb2" "attd_ks2_keys" "{'_id':{$ne : '_id'}}" ""
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        NoArgs = 6 # number of Args expected to process this Task
        MyUtilityName = "Run a dos command"
        DoAbort = False
        MyReturn = 0

        MyHost = None #MyArgList(0)
        MyOut = None #MyArgList(1)
        MyFF = None #MyArgList(2)
        MyDB = None #MyArgList(3)
        MyColl = None #MyArgList(4)
        MyQ = None #MyArgList(5)
        MyOther = None #MyArgList(6)

        b1 = "mongoexport.exe"
        b2 = None

        try :
            self.Write_Prompt()
            self.ConsoleWithTimeStamp("Starting MongoDB Export Applet, v1.1")
            if self.SHisSHEntry is True :
                b2 = '"{0}"'.format(os.path.join(self.gTempDir, b1))
            elif self.gMyLocal == "N" :
                b2 = '{0}'.format(os.path.join(self.gSPFVaryLib, b1))
            else :
                b2 = '"{0}"'.format(os.path.join(self.gMyLocal, b1))
            

            self.logger.debug("{0} - b1: '{1}'".format(calling_func, b1))
            self.logger.debug("{0} - b2: '{1}'".format(calling_func, b2))

            MyHost = self.MyUtilities[1] #MyArgList(0)
            MyOut = self.MyUtilities[2] #MyArgList(1)
            MyFF = self.MyUtilities[3] #MyArgList(2)
            MyDB = self.MyUtilities[4] #MyArgList(3)
            MyColl = self.MyUtilities[5] #MyArgList(4)
            MyQ = self.MyUtilities[6].strip() #MyArgList(5)
            MyOther = self.MyUtilities[7] #MyArgList(6)

            if (self.IsEmptyOrNone(MyDB) is True 
                or self.IsEmptyOrNone(MyColl) is True 
                or self.IsEmptyOrNone(MyOut) is True 
                or self.IsEmptyOrNone(MyFF) is True) :
                errMsg = ("Missing arguments:\n"
                          "     DB: {MyDB}\n"
                          "   Coll: {MyColl}\n"
                          " Output: {MyOut}\n"
                          " Fields: {MyFF}\n"
                          "Aborting ...").format(MyDB=MyDB, MyColl=MyColl, MyOut=MyOut, MyFF=MyFF)
                raise Exception(errMsg)
            
            MyFF = os.path.abspath(MyFF)
            self.logger.debug("{0} - MyHost: '{1}'".format(calling_func, MyHost))
            self.logger.debug("{0} - MyOut: '{1}'".format(calling_func, MyOut))
            self.logger.debug("{0} - MyFF: '{1}'".format(calling_func, MyFF))
            self.logger.debug("{0} - MyDB: '{1}'".format(calling_func, MyDB))
            self.logger.debug("{0} - MyColl: '{1}'".format(calling_func, MyColl))
            self.logger.debug("{0} - MyQ: '{1}'".format(calling_func, MyQ))
            self.logger.debug("{0} - MyOther: '{1}'".format(calling_func, MyOther))

            if os.path.exists(MyFF) is False :
                errMsg = ("Could not Find Field File {0}\n"
                          "Aborting ...").format(MyFF)
                raise Exception(errMsg)

            MyFF = '--fieldFile "{0}"'.format(MyFF)
            self.logger.debug("{0} - MyFF: '{1}'".format(calling_func, MyFF))

            """
            '====================
            'Get Query/Query File
            '====================
            """
            if self.IsEmptyOrNone(MyQ) is False :
                if MyQ.startswith("{") :
                    MyQ = '-q "{0}"'.format(MyQ)
                else :
                    MyQ = os.path.abspath(MyQ)
                    if os.path.exists(MyQ) is False :
                        errMsg = ("Could not Find Query File {0}\n"
                                  "Aborting ...").format(MyQ)
                        raise Exception(errMsg)
                    MyQ = '--queryFile "{0}"'.format(MyQ)

            """
            '=============
            'Get Host
            '=============
            """
            MyHostArr = MyHost.split("@")
            self.logger.debug("{0} - MyHostArr: '{1}'".format(calling_func, MyHostArr))
            MyHosti = MyHostArr[0].strip()
            self.logger.debug("{0} - MyHosti: '{1}'".format(calling_func, MyHosti))
            MyU = None
            try :
                MyU = MyHostArr[1].strip()
                if self.IsEmptyOrNone(MyU) is False :
                    MyU = re.sub("<at-sign>", "@", MyU)
                    MyU = '-u "{0}"'.format(MyU)
            except Exception as err:
                self.logger.warn("{0} - MyU - {1}".format(calling_func, err.args[0]))
                #pass -- continue
            self.logger.debug("{0} - MyU: '{1}'".format(calling_func, MyU))

            MyP = None
            try :
                MyP = MyHostArr[2].strip()
                if self.IsEmptyOrNone(MyP) is False :
                    MyU = re.sub("<at-sign>", "@", MyP)
                    MyP = '-p "{0}"'.format(MyP)
            except Exception as err:
                self.logger.warn("{0} - MyP - {1}".format(calling_func, err.args[0]))
                #pass -- continue
            self.logger.debug("{0} - MyP: '{1}'".format(calling_func, MyP))

            del MyHostArr

            MyHosti = "-h {0}".format("localhost:27017" if self.IsEmptyOrNone(MyHosti) is True else MyHosti)

            MyType="--type csv"

            MyDB = '-d "{0}"'.format(MyDB)
            MyColl = '-c "{0}"'.format(MyColl)
            MyOut = os.path.abspath(MyOut)
            MyOut = '-o "{0}"'.format(MyOut)

            cmdToExec = b2
            cmdArgs = [MyHosti, MyU, MyP, MyDB, MyColl, MyType, MyOut, MyFF, MyQ, MyOther]
            runStatus, MyReturn = self.Run(cmdToExec, cmdArgs)
                        
            self.ConsoleDoneWithTimeStamp2()
        except Exception as err: 
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            self.Site_Loop_Cleanup("")
            self.gMyAbort = True
            raise
#END : class MongoExportTask


