class MongoExtractTask(SPFTaskBase) :
    def __init__(self, SPFTaskItemIn=None, SPFTaskItemIdxIn=None):
        super(MongoExtractTask, self).__init__(SPFTaskItemIn, SPFTaskItemIdxIn)
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        self.logger.debug("{0} - MongoExtractTask Initialized".format(calling_func))
        return None

    def executeTaskCommand(self):
        r"""
        ' Overridden base method. Implementation of MongoExtract() -- 
        ''===== v30.67 ==========
        '====================================================
        'Extract filtered collection to a CSV file from MongoDB DB
        '
        'Args:
        '====
        'MyLocal: Local Exe Dir or N or ...py EE: self.gMyLocal
        'MyInstance : SPF Instance # -- py EE: self.gSPFInstance
        'MyHost : Host and Port to Connect to. Format host:port@un@pw
        'MyOut  : Output File
        'MyFF   : Field File
        'MyQ    : Query or _ID File or Empty
        'MyCollection: Collection Name
        'MyRows : Row Increment
        'MyOther: Other Options (e.g., --limit=10) 
        'FillPCT: Fill Percent Threshold
        'MyWRows: Write Rows (Chunk Size)
        '
        'GLOBALS:
        '-------
        'gTempDir    : SPF SW on Drones
        'gLocalDir   : Local Folder
        'gMyAbort    : Job Abort global
        'gSHFolder   : SH Analysis SPF SHare
        '
        '====================================================
        #v30.67 --> sample input line: /UTILITIES=@EXEDIR@\MongoDB-Extract.va "127.0.0.1:27017" "out.csv" "" "" "5" "1" "--limit='100'" 
        #v30.76 --> sample input line: ?? (TBD)
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        NoArgs = 8 # number of Args expected to process this Task #'===== v30.76 ==========
        MyUtilityName = "MONGOEXTRACT"
        DoAbort = False
        MyReturn = 0

        MyHost = None #MyArgList(0)
        MyOut = None #MyArgList(1)
        MyFF = None #MyArgList(2)
        MyQ = None #MyArgList(3)
        MyCollection = None #MyArgList(4) #'===== v30.76 ==========
        MyRows = None #MyArgList(5)
        MyOther = None #MyArgList(6)
        FillPCT = None #MyArgList(7) #'===== v30.76 ==========
        MyWRows = None #MyArgList(8)

        MySplit = "@"#'===== v30.76 ==========
        b1 = "mongoextract.py"
        b2 = None

        try :
            self.Write_Prompt()
            self.ConsoleWithTimeStamp("Starting MongoDB Extract Applet, v1.1")
            if self.SHisSHEntry is True :
                b2 = '"{0}"'.format(os.path.join(self.gTempDir, b1))
            elif self.gMyLocal == "N" :
                b2 = '{0}'.format(os.path.join(self.gSPFVaryLib, b1))
            else :
                b2 = '{0}'.format(os.path.join(self.gMyLocal, b1))
            

            self.logger.debug("{0} - b1: '{1}'".format(calling_func, b1))
            self.logger.debug("{0} - b2: '{1}'".format(calling_func, b2))
            #get the input parameters
            MyHost = self.MyUtilities[1] #MyArgList(0)
            MyOut = self.MyUtilities[2] #MyArgList(1)
            MyFF = self.MyUtilities[3] #MyArgList(2)
            MyQ = self.MyUtilities[4] #MyArgList(3)
            MyCollection = self.MyUtilities[5] #MyArgList(4) #'===== v30.76 ==========
            MyRows = self.MyUtilities[6].strip() #MyArgList(5)
            MyOther = self.MyUtilities[7].strip() #MyArgList(6)
            FillPCT = self.MyUtilities[8].strip() #MyArgList(7) #'===== v30.76 ==========
            MyWRows = self.MyUtilities[9].strip() #MyArgList(8)

            if self.IsEmptyOrNone(MyFF) is False:
                MyFF = os.path.abspath(MyFF)
            self.logger.debug("{0} - MyHost: '{1}'".format(calling_func, MyHost))
            self.logger.debug("{0} - MyOut: '{1}'".format(calling_func, MyOut))
            self.logger.debug("{0} - MyFF: '{1}'".format(calling_func, MyFF))
            self.logger.debug("{0} - MyQ: '{1}'".format(calling_func, MyQ))
            self.logger.debug("{0} - MyRows: '{1}'".format(calling_func, MyRows))
            self.logger.debug("{0} - MyWRows: '{1}'".format(calling_func, MyWRows))
            self.logger.debug("{0} - MyOther: '{1}'".format(calling_func, MyOther))

            """
            '====================
            'Get Query/_id File
            '====================
            """
            if self.IsEmptyOrNone(MyQ) is False :
                if MyQ.startswith("{") :
                    MyQ = '-q "{0}" -i ""'.format(MyQ)
                else : #'_id  File
                    MyQ = os.path.abspath(MyQ)
                    if os.path.exists(MyQ) is False :
                        errMsg = ("Could not Find _id File {0}\n"
                                  "Aborting ...").format(MyQ)
                        raise Exception(errMsg)
                    MyQ = '-i "{0}" -q ""'.format(MyQ)

            if self.IsEmptyOrNone(MyOut) is False :
                MyOut = os.path.abspath(MyOut)
            if self.IsEmptyOrNone(MyFF) is False :
                MyFF = os.path.abspath(MyFF)

            """
            '=============
            'Get Host
            '=============
            """
            #'===== v30.76 ==========
            if MyHost.find("<@>") > -1 :
                MySplit = "<@>"
            MyHostArr = MyHost.split(MySplit)

            self.logger.debug("{0} - MyHostArr: '{1}'".format(calling_func, MyHostArr))
            if len(MyHostArr) >= 5 :
                MyHostArr[4] = self.Drb(MyHostArr[4])
                MyHostArr.insert(2, MyCollection)
                MyHost = "<@>".join(itemgetter(0,1,2,4,5)(MyHostArr))
            else :
                errMsg = "The Connection String is not in the correct format\nAborting ..."
                raise Exception(errMsg)

            self.logger.debug("{0} - MyHost: '{1}'".format(calling_func, MyHost))
            del MyHostArr

            Tmp = (' -m  "{MyHost}"'
                  ' -o "{MyOut}"'
                  ' {MyQ}'
                  ' -f "{MyFF}"'
                  ' -r "{MyRows}"'
                  ' -w "{MyWRows}"'
                  ' -p "{FillPCT}"' #'===== v30.68 ==========
                  ' {MyOther}').format(MyHost=MyHost,
                                      MyOut=MyOut,
                                      MyQ = MyQ,
                                      MyFF=MyFF,
                                      MyRows=MyRows,
                                      MyWRows=MyWRows,
                                      FillPCT=FillPCT, #'===== v30.68 ==========
                                      MyOther=MyOther.replace("'", '"')) 
                                                                                   
            self.logger.debug("{0} - Tmp: '{1}'".format(calling_func, Tmp))
            self.Run_Python(b2, Tmp, None, self.gMyLocal, self.gSPFInstance, None)
            self.ConsoleDoneWithTimeStamp2()
        except Exception as err: 
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            self.Site_Loop_Cleanup("")
            self.gMyAbort = True
            raise
#END : class MongoExtractTask

