class GetHelpCSVTask(SPFTaskBase) :
    def __init__(self, SPFTaskItemIn=None, SPFTaskItemIdxIn=None):
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        super(GetHelpCSVTask, self).__init__(SPFTaskItemIn, SPFTaskItemIdxIn)
        self.logger.debug("{0} - GetHelpCSVTask Initialized".format(calling_func))
        return None
    def executeTaskCommand(self):
        r"""
        ' Implementation of GetHelpCSV.va
        'History: 
        '1.0.0.0 : 09/12/2017 : Nataraj : Initial Version
        '==================================================================
        ' Procedure: GetHelpCSV               Date: 09/12/2017
        '
        ' Arguments:
        ' =========
        '   1. SQL Query of format "select <columns> FROM [<table>.csv] <alias>"
        '
        ' Sample Invocation:
        ' =================
        '/UTILITIES=@EXEDIR@\GetHelpCSV.va "Select DISTINCT [operation] From [10035.tab]"
        '==================================================================
        """
        #region locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        NoArgs = 1 # number of Args expected to process this Task 
        MyUtilityName = "GetHelpCSV"
        WorkDir = ".\\"
        rePtrnSrcColFile = r"^SELECT\s*DISTINCT\s*\[?(?P<SrcCol>.*?)\]?\s*FROM\s*\[?(?P<SrcFile>.*[\.csv|.\tab])\]?"
        SrcCol = None
        SrcFile = None
        Src_dlm = None
        MySQL = None #MyArgList(0)
        #endregion locals

        try:
            self.Write_Prompt()
            self.ConsoleWithTimeStamp("Starting script GetCSVHelp, V1.0")
            
            #get the input parameters
            errMsg_NoSQLQuery = "No SQL Query passed as an Input argument."
            try:
                MySQL = self.MyUtilities[1] #MyArgList(0)
                if self.IsEmptyOrNone(MySQL) is False:
                    self.Console("SQL Query to process  : {0}".format(MySQL))
                else:
                    raise Exception("Empty Query : MySQL : {0}".format(MySQL))
            except Exception as err:
                self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
                raise Exception(errMsg_NoSQLQuery)

            OutFile = os.path.join(WorkDir, "SPF_Help_Data.txt") #'Tab delimited Output File
            self.logger.debug("OutFile : {0}".format(OutFile))
            reMatchObj = re.search(rePtrnSrcColFile, MySQL, re.IGNORECASE)
            if reMatchObj:
                SrcCol = reMatchObj.group("SrcCol")
                SrcFile = reMatchObj.group("SrcFile")
            else:
                errMsg = 'Unusual SQL Query passed to Job. \n\tEither No "FROM" Clause present \n\t\t\tOR \n\tUnusual CSV/TAB File used in SQL Query. \nExiting...'
                raise Exception(errMsg)

            Src_dlm = self.GetFileDLM(SrcFile)
            SrcFile_name, SrcFile_ext = os.path.splitext(SrcFile)
            self.logger.debug("SrcCol : {0}".format(SrcCol))
            self.logger.debug("SrcFile : {0}".format(SrcFile))
            self.logger.debug("SrcFile_name : {0}".format(SrcFile_name))
            self.logger.debug("SrcFile_ext : {0}".format(SrcFile_ext))
            self.logger.debug("Src_dlm : '{0}'".format(Src_dlm))

            self.Console("{0} File to Process   : {1}".format(SrcFile_ext.strip(".").upper(), SrcFile))
            self.Console("Starting SQL Text Query to Display Results...\n")

            SrcColData = self.getUniqueValuesInColumn(SrcFile, SrcCol, Src_dlm)
            SrcColDataLen = len(SrcColData)
            SrcColData = "\n".join(SrcColData)
            self.logger.debug("len(SrcColData) : '{0}'".format(len(SrcColData)))
            #df1 = pd.DataFrame(SrcColData, columns=["{0}R_{1}".format(len(SrcColData), SrcCol)], dtype=str)
            #self.writeDFtoFile(df1, OutFile, ",", "", createNew=True)
            #df1.columns = [SrcCol]
            self.Console("\n{0}".format(SrcCol))
            self.Console("-" * SrcColDataLen)
            #self.Send_To_Term (OutFile, True, ll_NoHdrs=True)
            with open(OutFile, "wb") if isPYTHON2 is True else open(OutFile, "w", encoding=self.gOSDefaultEncoding, errors='replace') as OutFileWrtr :
                OutFileWrtr.write("{0}R_{1}".format(SrcColDataLen, SrcCol))
                OutFileWrtr.write(SrcColData)
                self.Console(SrcColData)
            self.Console("\n{0}  rows\n".format(SrcColDataLen))
            self.ConsoleDoneWithTimeStamp()
        except Exception as err: 
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            self.Site_Loop_Cleanup("")
            self.gMyAbort = True
            raise
#END : class GetHelpCSVTask

