class GetFilesTask(SPFTaskBase):
    def __init__(self, SPFTaskItemIn=None, SPFTaskItemIdxIn=None):
        super(GetFilesTask, self).__init__(SPFTaskItemIn=SPFTaskItemIn, SPFTaskItemIdxIn=SPFTaskItemIdxIn)
        #local variables
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        self.outputColumns = ['Path', 'Filename', 'Last_Modified_Date','Last_Access_Date','Creation_Date', 'Size']
        self.logger.debug("{0} - GetFilesTask Initialized".format(calling_func))
        return
   
    def executeTaskCommand(self):
        """
        sample input : 
        <OPTIONS>
        /WORKDIR=.\
        /INSTANCE=20
        /UTILITIES={GET-FILES} "c:\temp" "Y" "OutputDirTable.tab"
        /PROMPT-TEXT=Generate a Table of Files in a directory at <<<spf_datetime>>>
        </OPTIONS>
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        myPathToRead = os.path.abspath(".\\")
        self.OutExcel = "SPFDirTable_output.tab"
        myIncludeSubFolders = "N"

        self.Write_Prompt()
        self.ConsoleWithTimeStamp("Get Files in a folder Utility, v 2.0")
        #parse utility arguments
        try:
            myPathToRead = os.path.expandvars(self.MyUtilities[1])
            self.logger.debug("{0} - myPathToRead : {1}".format(calling_func, myPathToRead))
        except Exception as err:
            self.logger.warn("{0} - {1}...continue with 'Path to Scan' default value : {2}".format(calling_func, err.args[0], myPathToRead))
            pass #continue with default myPathToRead = ".\\"

        try:
            myIncludeSubFolders = self.MyUtilities[2]
            self.logger.debug("{0} - myIncludeSubFolders : {1}".format(calling_func, myIncludeSubFolders))
        except Exception as err:
            self.logger.warn("{0} - {1}...continue with 'Include Subfolders' default value : {2}".format(calling_func, err.args[0], myIncludeSubFolders))
            pass #continue with myIncludeSubFolders = "N"

        try:
            self.OutExcel = os.path.abspath(os.path.expandvars(self.MyUtilities[3]))
            self.logger.debug("{0} - OutExcel : {1}".format(calling_func, self.OutExcel))
        except Exception as err:
            self.logger.warn("{0} - {1}...continue with 'Outputfile' default value : {2}".format(calling_func, err.args[0], self.OutExcel))
            raise

        try:
            self.ContinueOnError = self.convertYNToBool(self.MyUtilities[4])
            self.logger.debug("{0} - continueOnErr : {1}".format(calling_func, self.ContinueOnError))
        except Exception as err:
            self.logger.warn("{0} - {1}...continue with default value : {2}".format(calling_func, err.args[0], self.ContinueOnError))
            raise

        self.ConsStar80()
        self.Console("Path to Scan      : {0}".format(myPathToRead))
        self.Console("Include Subfolder : {0}".format(myIncludeSubFolders))
        self.Console("Outputfile        : {0}".format(self.OutExcel))
        self.Console("Continue on Error : {0}".format(self.convertBoolToYN(self.ContinueOnError)))
        self.ConsStar80()
        self.Console()
        try:
            self.DelAFile(self.OutExcel)
            try: 
                outputFileInfoArr = self.getFilesInfoFromFolderGlob(myPathToRead, self.getBoolOptValue("IncludeSubFolder", myIncludeSubFolders))
                filesCount = self.writeGetFilesOutput(outputFileInfoArr)
                self.ConsoleWithTimeStamp(f"  Done... Found {filesCount} file(s)")
            except IOError as IOerr:
                errMsg = "I/O Error({0}): {1} \n File : {2}".format(IOerr.errno, IOerr.strerror, IOerr.filename)
                raise Exception(errMsg)
            except Exception as err:
                raise
        except Exception as err:
            if self.ContinueOnError is True:
                self.ConsoleErrMsgContinue(err)
                self.writeGetFilesOutput([]) # write headeronly
            else:
                self.logger.exception("{0} - {1}".format(calling_func, err))
                raise

        self.ConsoleDoneWithTimeStamp()
    #END :  def executeTaskCommand

    def writeGetFilesOutput(self, outputFileInfoArr):
        """
        helper function to write output file
        """
        df1 = pd.DataFrame(outputFileInfoArr, columns=self.outputColumns, dtype=str)
        df1.dropna(inplace=True)
        filesCount = len(df1)
        self.writeDFtoFile(df1, self.OutExcel, self.GetFileDLM(self.OutExcel), "", True)
        del df1
        return filesCount

    def getFilesInfoFromFolderGlob(self, myPathToRead, includeSubFolder=False):
        """
        helper function to scan for files matching the given pattern -- using pathlib.Path
        """
        #region locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        self.logger.debug("{0} - myPathToRead : {1}".format(calling_func, myPathToRead))
        self.logger.debug("{0} - includeSubFolder : {1}".format(calling_func, includeSubFolder))
        output_FilesInfoArr = []
        found_wild_card = False
        #endregion locals
        try:
            try:
                if Path(myPathToRead).is_dir() is True:
                    #this is path to a directory without any wildcards...add the *.*
                    self.logger.debug("{0} - Path points to a folder: {1}".format(calling_func, myPathToRead))
                    myPathToRead = rf"{myPathToRead}\*.*"
                    self.logger.debug("{0} - Updated Path : {1}".format(calling_func, myPathToRead))
            except Exception as err:
                #path is not plain directory...
                #continue
                pass

            if myPathToRead == ".\\":
                myPathToRead = r".\*.*"
            if myPathToRead.startswith(".\\") is True:
                myPathToRead = str(Path(myPathToRead).absolute())
                self.logger.debug("{0} - absolute myPathToRead : {1}".format(calling_func, myPathToRead))
            path_parts = Path(myPathToRead).parts
            path_parts_without_wildcard = [] #all parts of path till a wildcard is encountered
            path_parts_with_wildcard = [] #part of path with wildcard and rest parts of path

            for path_part in path_parts:
                if (path_part.find("*") > -1 
                or path_part.find("?") > -1 
                or  found_wild_card is True):
                    path_parts_with_wildcard.append(path_part)
                    found_wild_card= True
                else:
                    path_parts_without_wildcard.append(path_part)
            self.logger.debug("{0} - found_wild_card : {1}".format(calling_func, found_wild_card))
            
            #now construct the pathparts
            path_parent = "\\".join(path_parts_without_wildcard)
            path_glob_part = "\\".join(path_parts_with_wildcard) 

            if found_wild_card is False:
                self.logger.debug("{0} - single file : {1}".format(calling_func, path_parent))
                _tmp = Path(path_parent)
                self.logger.debug("{0} - file exists: {1}".format(calling_func, _tmp.exists()))
                filesIterator = [_tmp] if _tmp.exists() else []
            else:
                if includeSubFolder is True:
                    filesIterator = Path(path_parent).rglob(path_glob_part)
                else:
                    filesIterator = Path(path_parent).glob(path_glob_part)

            for filePathObj in filesIterator:
                output_FilesInfoArr.append(self.getFileInfo(filePathObj))
        except Exception as err:
            if self.ContinueOnError is True:
                self.ConsoleErrMsgContinue(err)
            else:
                self.logger.exception("{0} - {1}".format(calling_func, err))
                raise
        return output_FilesInfoArr

    def getFileInfo(self, filePathObj):
        """
        helper function to get info of file -- using pathlib.Path
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        self.logger.debug("{0} - filePathObj : {1}".format(calling_func, filePathObj))
        if type(filePathObj) not in [pathlib.WindowsPath, pathlib.PosixPath, pathlib.PureWindowsPath, pathlib.Path]:
            errMsg = f"Unsupported Path object : {type(filePathObj)}"
            raise Exception(err)

        statResult = filePathObj.stat()
        return [str(filePathObj.parent), filePathObj.name, 
                datetime.strftime(datetime.fromtimestamp(statResult.st_mtime), self.G_DT_FORMAT_YYYY_M_DD_HH24_MM_SS), 
                datetime.strftime(datetime.fromtimestamp(statResult.st_atime), self.G_DT_FORMAT_YYYY_M_DD_HH24_MM_SS), 
                datetime.strftime(datetime.fromtimestamp(statResult.st_ctime), self.G_DT_FORMAT_YYYY_M_DD_HH24_MM_SS), 
                int(statResult.st_size)]
#END : class GetFilesTask 

class FileCompareTask(SPFTaskBase):
    """
    """
    def __init__(self, SPFTaskItemIn=None, SPFTaskItemIdxIn=None):
        super(FileCompareTask, self).__init__(SPFTaskItemIn=SPFTaskItemIn, SPFTaskItemIdxIn=SPFTaskItemIdxIn)
        #local variables
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        self.logger.debug("{0} - FileCompareTask Initialized".format(calling_func))
        return
   
    def getDiffInLines(self, myLine1, myLine2):
        """
        helper function to get the mismatch in lines using difflib
        """
        #local variables
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        #self.logger.debug("{0} - myLine1 : {1}".format(calling_func, myLine1))
        #self.logger.debug("{0} - myLine2 : {1}".format(calling_func, myLine2))
        mydiff2 = difflib.Differ().compare([myLine1], [myLine2])
        return "\n".join(mydiff2)

    def maskDate(self, myLine1, myLine2, myDateFormatRePattern, myDateMask):
        """
        helper function to mask date values in lines
        """
        #local variables
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        #self.logger.debug("{0} - myLine1 : {1}".format(calling_func, myLine1))
        #self.logger.debug("{0} - myLine2 : {1}".format(calling_func, myLine2))
        myLine1 = re.sub(myDateFormatRePattern, myDateMask, myLine1, 0, re.IGNORECASE)
        myLine2 = re.sub(myDateFormatRePattern, myDateMask, myLine2, 0, re.IGNORECASE)
        return myLine1, myLine2

    def executeTaskCommand(self):
        """
        /UTILITIES={FILE-COMPARE} "MasterFile1:STI_XEUS_Py_EAN-N_DType-Num-All.csv" "FileNew1:STI_XEUS_Py_EAN-Y_DType-Num-All.csv" "CASE-SENSITIVE:Y" "CONTINUE-ON-ERROR:Y" "MAXNumMismatches:10" "DATEFORMATforMasking:YYYY-MM-DD HH:MM:SS" "NotifyForMismatch:Y/N" 
        sample input : 
        <OPTIONS>
        /WORKDIR=.\
        /INSTANCE=24542
        /OUTLOOK=Y
        /UTILITIES={FILE-COMPARE} "MasterOutput_1.csv" "NewOutput1.csv" "Y" "Y" "10" "DATE-FORMAT=YYYY-MM-DD HH:MM:SS" "Y"
        /PROMPT-TEXT=Step 1. Compare Files
        </OPTIONS>
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        myFile1 = ""
        myFile2 = ""
        myCaseInsensitiveCompareFlag = False #default comparision is case sensitive
        myDefaultDateFormat = "YYYY-MM-DD HH:MI:SS"
        #dateMaskRegexPatternLookup = {DateFormatFromUser : (regexPattern, ValueThatWillBeReplaceWith)
        dateMaskRegexPatternLookup = {"YYYY-MM-DD HH:MI:SS" : (r"\d{4}-\d{2}-\d{2}\s\d{2}:\d{2}:\d{2}", "2019-12-01 23:59:59")}
        myDateFormatRePattern, myDateMask = ("", "")
        maxMismatches = 0
        notifyOnMismatch = True
        consMsg = None
        compareMsg = None
        self.Write_Prompt()
        self.ConsoleWithTimeStamp("Compare Files Utility, v 1.0")
        try:
            #parse utility arguments
            try:
                myFile1 = os.path.abspath(os.path.expandvars(self.MyUtilities[1]))
                self.logger.debug("{0} - myFile1 : {1}".format(calling_func, myFile1))
                if re.search("<<<spf-cw#-ctr>>>", myFile2, re.IGNORECASE):
                    myFile2 = re.sub("<<<spf-cw#-ctr>>>",str(self.g_ChartCtr), myFile2,0,re.IGNORECASE)
                    self.logger.debug("{0} - substitute <<<spf-cw#-ctr>>> in myFile1 : {1}".format(calling_func, myFile2))
            except Exception as err:
                errMsg = "{0}...\nFile 1 is missing in input : {1}".format(err.args[0], myFile1)
                self.logger.exception("{0} - {1}".format(calling_func, err))
                raise Exception(errMsg)

            try:
                myFile2 = os.path.abspath(os.path.expandvars(self.MyUtilities[2]))
                self.logger.debug("{0} - myFile2 : {1}".format(calling_func, myFile2))
                if re.search("<<<spf-cw#-ctr>>>", myFile2, re.IGNORECASE):
                    myFile2 = re.sub("<<<spf-cw#-ctr>>>",str(self.g_ChartCtr), myFile2,0,re.IGNORECASE)
                    self.logger.debug("{0} - substitute <<<spf-cw#-ctr>>> in myFile2 : {1}".format(calling_func, myFile2))
            except Exception as err:
                errMsg = "{0}...\nFile 2 is missing in input : {1}".format(err.args[0], myFile2)
                self.logger.exception("{0} - {1}".format(calling_func, errMsg))
                raise Exception(errMsg)

            try:
                myCaseInsensitiveCompareFlag = self.convertYNToBool(self.MyUtilities[3])
            except Exception as err:
                pass #continue with default
            self.logger.debug("{0} - Case-Insensitive Compare Flag : {1}".format(calling_func, myCaseInsensitiveCompareFlag))

            try:
                self.ContinueOnError = self.convertYNToBool(self.MyUtilities[4])
            except Exception as err:
                pass #continue with default
            self.logger.debug("{0} - ContinueOnError : {1}".format(calling_func, self.ContinueOnError))

            try:
                maxMismatches = int(self.MyUtilities[5].strip())
                if maxMismatches < 0: 
                    maxMismatches = 0
            except Exception as err:
                pass #continue with default
            self.logger.debug("{0} - maxMismatches : {1}".format(calling_func, maxMismatches))

            try:
                myDateFormat = self.MyUtilities[6].strip().upper()
                if self.IsEmptyOrNone(myDateFormat) is False:
                    myDateFormatRePattern, myDateMask = dateMaskRegexPatternLookup[myDateFormat]

            except Exception as err:
                #myDateFormatRePattern, myDateMask = dateMaskRegexPatternLookup[myDefaultDateFormat]
                pass #continue with default dont perform Datetimestamp replace
            self.logger.debug("{0} - myDateFormat : {1}".format(calling_func, myDateFormat))
            self.logger.debug("{0} - myDateFormatRePattern : {1}".format(calling_func, myDateFormatRePattern))
            self.logger.debug("{0} - myDateMask : {1}".format(calling_func, myDateMask))

            try:
                notifyOnMismatch = self.convertYNToBool(self.MyUtilities[7])
            except Exception as err:
                pass #continue with default
            self.logger.debug("{0} - Notify On Mismatch : {1}".format(calling_func, notifyOnMismatch))

            if os.path.exists(myFile1) is False:
                errMsg = "File 1 : {0}\n ...File not found".format(myFile1)
                raise Exception(errMsg)

            if os.path.exists(myFile2) is False:
                errMsg = "File 2 : {0}\n ...File not found".format(myFile2)
                raise Exception(errMsg)

            consMsg = ("Starting Files Comparison:\n"
                       "File 1              : {myFile1}\n"
                       "File 2              : {myFile2}\n"
                       "Case Insensitive    : {myCaseInsensitiveCompareFlag}\n"
                       "Date Mask           : {myDateMask}\n"
                       "Continue On Error   : {ContinueOnError}\n"
                       "Max Mismatches      : {maxMismatches}\n"
                       "Notify on Mismatch  : {notifyOnMismatch}").format(myFile1=myFile1,
                                                                myFile2=myFile2,
                                                                myCaseInsensitiveCompareFlag=self.convertBoolToYN(myCaseInsensitiveCompareFlag),
                                                                myDateMask=myDateMask,
                                                                ContinueOnError = self.convertBoolToYN(self.ContinueOnError),
                                                                maxMismatches=maxMismatches,
                                                                notifyOnMismatch=self.convertBoolToYN(notifyOnMismatch))
            self.ConsoleWithConsStar80(consMsg)
            self.Console()
        
            compareMsg = "\n\n{0}\n\n{1}\n\n\t...{2}"
            if filecmp.cmp(myFile1, myFile2) is True:
                compareMsg = "...files matched\n"
                self.ConsoleWithCons80(compareMsg)
            else:
                compareMsgArr = []
                mismatchCount = 0

                
                #Check for rowcount mismatch
                myFile1LinesCount = self.getLineCountFromFile(myFile1)
                myFile2LineCount = self.getLineCountFromFile(myFile2)
                if myFile1LinesCount != myFile2LineCount:
                    mismatchCount = mismatchCount + 1
                    compareMsgArr.append("{0}\n\n{1}\n\n\t".format("File 1 - Row/Line Count : {myFileLinesCount}".format(myFileLinesCount=myFile1LinesCount), 
                                                   "File 2 - Row/Line Count : {myFileLinesCount}".format(myFileLinesCount=myFile2LineCount), 
                                                   "files Row/Line count don't match\n"))

                #passed Row/Line count check...continue with each row/line comparision
                if myCaseInsensitiveCompareFlag is False:
                    reFlags = 0
                else:
                    reFlags = re.IGNORECASE
                self.logger.debug("{0} - reFlags : {1}".format(calling_func, reFlags))
                with open(myFile1, "r") if isPYTHON2 is True else open(myFile1, "r", encoding=self.detectFileEncoding(myFile1), errors='replace') as myFile1Rdr, open(myFile2, "r") if isPYTHON2 is True else open(myFile2, "r", encoding=self.gOSDefaultEncoding, errors='replace') as myFile2Rdr:
                    lineCount = 1
                    
                    for myFile1Line, myFile2Line in izip(myFile1Rdr, myFile2Rdr) if isPYTHON2 else zip(myFile1Rdr, myFile2Rdr):
                        if self.IsEmptyOrNone(myDateMask) is False:
                            myFile1Line, myFile2Line  = self.maskDate(myFile1Line, myFile2Line, myDateFormatRePattern, myDateMask)
                        if re.match(re.escape(myFile1Line), myFile2Line, reFlags) is None:
                            mismatchCount = mismatchCount + 1
                            #mismatch display the line to console and raise error
                            compareMsgArr.append("...Mismatch in line {0}\n\n{1}".format(lineCount, self.getDiffInLines(myFile1Line, myFile2Line)))
                        if maxMismatches != 0 and mismatchCount >= maxMismatches:
                            break;
                        lineCount = lineCount + 1
                self.logger.debug("{0} - compareMsgArr : {1}".format(calling_func, compareMsgArr))
                if len(compareMsgArr) > 0:
                    self.Console("...files don't match\n")
                    compareMsg = "{1}\n\nTotal mismatches : {0}".format(mismatchCount, "\n{0}\n".format(40 * "*").join(compareMsgArr))
                    raise Exception(compareMsg)
                elif myCaseInsensitiveCompareFlag is True:
                    compareMsg = "...files are different but matched with Case-insensitive compare\n"
                    self.ConsoleWithCons80(compareMsg)
                else: #this could be due to line-feed characters \n vs \r\n
                    compareMsg = "...files are different only in line-feed characters\n"
                    self.ConsoleWithCons80(compareMsg)
            #END: if filecmp.cmp(myFile1, myFile2) is True:
            self.ConsoleDoneWithTimeStamp()
        except Exception as err:
            if compareMsg is None:
                compareMsg = err.args[0]
            if consMsg is None:
                consMsg = ""
            if notifyOnMismatch is True:
                #write mismatches to HTML file for attachment
                emailBodyFile = "{0}_FC-NotifyAttach.htm".format(self.RandomNumStr)
                emailBodyContent = "<HTML><Body>{0}<hr>{1}<hr></Body></HTML>".format(consMsg.replace("\n","<br>"), compareMsg.replace("\n","<br>"))
                emailSubject = "SQLPathFinder - File compare failed for : '{0}' & '{1}'".format(os.path.split(myFile1)[1], os.path.split(myFile2)[1])
                self.DoCreateFileA(emailBodyFile, emailBodyContent, "FileCompareTask")
                self.SPFEmail(self.gMyLocal,"", 'self', emailSubject, emailBodyFile, '','', '', True, False)
                if os.path.isfile(emailBodyFile) is True:
                    self.DelAFile(emailBodyFile)
            if self.ContinueOnError is False:
                raise
            else:
                self.ConsoleWithCons80(err.args[0])
                self.ConsoleDoneWithTimeStamp()
#END : class FileCompareTask 

