class dbDriverUBER(dbDriverBase):
    """
    Class to instantiate UBER UniqeClientHelper object  ...support SQLPaaS
    """        
    #region constants
    OUTPUT_DATE_FORMAT = "yyyy-MM-dd HH:mm:ss"
    UBER_INSTALL_DIR = 'UBER_INSTALL_DIR'
    #endregion constants

    #region locals -- static
    isInitialized = False
    #endregion

    def __init__(self, MyAppSvr, queryOptions=None):
        """
        Initialize Uber .Net objects using clr module
        """
        import clr
        super(dbDriverUBER, self).__init__(queryOptions=queryOptions)

        global UniqeClientHelper, AuthMode

        self.uberInstallDirFrmEnvVar = os.getenv(self.UBER_INSTALL_DIR)
        #load the required UBER .net assemblies -- START
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        try :
            self.MyAppSvr = MyAppSvr
            if dbDriverUBER.isInitialized is False :
                if self.uberInstallDirFrmEnvVar is None:
                    errMsg = "Uber Installation path environment varialbe 'UBER_INSTALL_DIR' not found"
                    raise Exception(errMsg)
                
                sys.path.insert(0, os.path.join(self.uberInstallDirFrmEnvVar, 'BIN'))
                _tmp_uber_filepath = os.path.join(self.uberInstallDirFrmEnvVar, 'BIN', 'Intel.FabAuto.ESFW.DS.UBER.DataServiceFactory')
                if Path(f"{_tmp_uber_filepath}.dll").exists() is False:
                    errMsg = f"Uber DataServiceFactory assembly not found in expected location : {_tmp_uber_filepath}.dll"
                    raise Exception(errMsg)
                else:
                    self.logger.info(f"{calling_func} - Uber Assembly found : {_tmp_uber_filepath}.dll")

                clr.AddReference(_tmp_uber_filepath)
                from Intel.FabAuto.ESFW.DS.UBER import UniqeClientHelper, AuthMode
                #initialize local variables
                self.DataSource = None
                self.uberInstallDirFrmEnvVar = None
                self.uberTable = None
                self.UCHelper = None
                self.isInitialized = True
            self.logger.info(f"{calling_func} - {__name__}.{self.__class__.__name__} Initialized : {dbDriverUBER.isInitialized}")
        except Exception as err:
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise

    def openConnection(self, uni, pwi, InDBNode, ll_ConnRetry=True):
        """
        ' set Datasource...opening connection and other tasks are done in execute 
        """
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        try :
            self.DataSource = InDBNode.strip()
            for retry_Count in range(1,self.gMaxConnectRetry+1):
                try:
                    startTime = time.perf_counter()
                    self.UCHelper = UniqeClientHelper()
                    timeTaken = time.perf_counter() - startTime
                    self.logger.debug("{0} - UniqeClientHelper creation time taken : {1}".format(calling_func, timeTaken))
                    startTime = time.perf_counter()
                    self.UCHelper.DataSource = self.DataSource
                    #self.UCHelper.Site = "rf3sap1170w001.rf3stg.mfgint.intel.com"
                    self.UCHelper.Authentication = AuthMode.IIS if self.gIsSvc is True else AuthMode.IWA
                    self.UCHelper.UserId = None
                    self.UCHelper.Password = None
                    self.myUtils.Console("  Connected...\n")
                    break
                except Exception as err:
                    self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
                    if re.search('The wait operation timed out', err.args[0], re.IGNORECASE):
                        self.myUtils.Cons80()
                        self.myUtils.Console("Error Occured : {0}".format(err.args[0]))
                        self.myUtils.Console('\tWaiting {0} seconds before retry number {1} of {2}'.format(self.gRunTimer, retry_Count, self.gMaxConnectRetry))
                        self.myUtils.Cons80()
                        time.sleep(self.gRunTimer)
                        if retry_Count < self.gMaxConnectRetry:
                            pass #continue with retry
                        else:
                            self.logger.debug(f"Error even after retry...")
                            raise Exception(f"Uber Error even after retry: {err.args[0]}")
                    else:
                        #No error match -- raise error
                        self.logger.debug(f"Error no retry...")
                        raise Exception(f"Uber Error : {err.args[0]}")
            self.logger.info("{0} - create connection done".format(calling_func))
        except Exception as err:
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise

    def execute(self, SQLQuery, CommandHdr=None, MyFetchSize=10000, FirstConnect=True, 
                ll_NoHdrs=False, OutExcel=None, OutFile=None, WorkDir=".\\", OutTT=False, 
                FinalRow=0, incrementalRunCtr=0, doWriteDonePromptText=True, MyHeaders=None) :
        """
        ' Create UniqeClientHelper object and execute the SQLQuery
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        for retry_Count in range(1,self.gMaxConnectRetry+1):
            try :
                startTime = time.perf_counter()
                self.uberTable = self.UCHelper.GetUberTable(SQLQuery)
                self.logger.debug("{0} - uberTable.DataSource : {1}".format(calling_func, self.uberTable.DataSource))
                self.logger.debug("{0} - uberTable.Server : {1}".format(calling_func, self.uberTable.Server))
                timeTaken = time.perf_counter() - startTime
                self.logger.debug("{0} - Total time taken to complete Uber Query : {1}".format(calling_func, timeTaken))
                
                return self.saveResultToFile(MyFetchSize, FirstConnect, OutExcel, WorkDir, OutTT, incrementalRunCtr, ll_NoHdrs)
            except Exception as err:
                # self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
                # raise
                self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
                if re.search('The wait operation timed out', err.args[0], re.IGNORECASE) or re.search('ORA-01012: not logged on', err.args[0], re.IGNORECASE):
                    self.myUtils.Cons80()
                    self.myUtils.Console("Error Occured : {0}".format(err.args[0]))
                    self.myUtils.Console('\tWaiting {0} seconds before retry number {1} of {2}'.format(self.gRunTimer, retry_Count, self.gMaxConnectRetry))
                    self.myUtils.Cons80()
                    time.sleep(self.gRunTimer)
                    if retry_Count < self.gMaxConnectRetry:
                        pass #continue with retry
                    else:
                        self.logger.debug(f"Error even after retry...")
                        raise Exception(f"Uber Error even after retry: {err.args[0]}")
                else:
                    #No error match -- raise error
                    self.logger.debug(f"Error no retry...")
                    raise Exception(f"Uber Error : {err.args[0]}")
            finally :
                self.logger.info("{0} - execute() finally completed".format(calling_func))
    #END : def execute

    def executeParallel(self, SQLQuery, CommandHdr=None, MyFetchSize=10000, FirstConnect= True, ll_NoHdrs=False,
                OutExcel=None, OutFile=None, WorkDir=".\\", OutTT=False, FinalRow=0, incrementalRunCtr=0, doWriteDonePromptText=True, MyHeaders=None):
        """
        Call uber client with list of queries that will be executed in parallel in Uber 
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        uber_sqlqry_list = None
        startTime = time.perf_counter()
        try:
            uber_sqlqry_list = List[str]()
        except Exception as err:
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise
        try:
            self.logger.debug(f"len(SQLQuery) : {len(SQLQuery)}")
            for retry_Count in range(1,self.gMaxConnectRetry+1):
                self.logger.debug(f"retry_Count : {retry_Count}")
                try:
                    with SPFRichProgressBar() as progress: #, total=len(self.uberTables)):
                        task = progress.add_task(f"Fetching data in parallel", total=len(SQLQuery))
                        for item in SQLQuery:
                            uber_sqlqry_list.Add(item)
                        progress.update(task, advance=len(SQLQuery)-1)
                        self.uberTables = self.UCHelper.GetUberTables(uber_sqlqry_list)
                        progress.update(task, advance=1)
                    break #execution passed...break retry 'for retry_Count in range(1,self.gMaxConnectRetry+1):'
                except Exception as err:
                    self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
                    if re.search('The wait operation timed out', err.args[0], re.IGNORECASE) or re.search('ORA-01012: not logged on', err.args[0], re.IGNORECASE):
                        self.myUtils.Cons80()
                        self.myUtils.Console("Error Occured : {0}".format(err.args[0]))
                        self.myUtils.Console('\tWaiting {0} seconds before retry number {1} of {2}'.format(self.gRunTimer, retry_Count, self.gMaxConnectRetry))
                        self.myUtils.Cons80()
                        time.sleep(self.gRunTimer)
                        if retry_Count < self.gMaxConnectRetry:
                            pass #continue with retry
                        else:
                            self.logger.debug(f"Error even after retry...")
                            raise Exception(f"Uber Error even after retry: {err.args[0]}")
                    else:
                        #No error match -- raise error
                        self.logger.debug(f"Error no retry...")
                        raise Exception(f"Uber Error : {err.args[0]}")
            #END : for retry_Count in range(1,self.gMaxConnectRetry+1):
            # self.myUtils.Console("")
            timeTaken = time.perf_counter() - startTime
            self.logger.debug("{0} - Total time taken to complete Uber Query : {1}".format(calling_func, timeTaken))
            # self.Console("")
            #execution completed...write results to file(s)
            return self.saveMultiResultToFile(MyFetchSize, FirstConnect, OutExcel, WorkDir, OutTT, incrementalRunCtr, ll_NoHdrs)
        except Exception as err:
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise
        finally:
            # clean up
            uber_sqlqry_list = None
            timeTaken = time.perf_counter() - startTime
            self.logger.debug("{0} - Total time taken to complete Uber Query parallel : {1}".format(calling_func, timeTaken))
            

    def saveResultToFile(self, fetchChunkSize=10000, FirstConnect=True, OutExcel=None, WorkDir=".\\", outTTin=False, incrementalRunCtr=0, ll_NoHdrs=False) :
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        try : 
            self.logger.debug("{0} - ll_NoHdrs : {1}".format(calling_func, ll_NoHdrs))
            self.logger.debug("{0} - FirstConnect : {1}".format(calling_func, FirstConnect))
            rowCount = 0
            append = True
            if FirstConnect == True :
                append = False
            else :
                ll_NoHdrs = True

            self.logger.debug("{0} - ll_NoHdrs : {1}".format(calling_func, ll_NoHdrs))
            
            fileDLM = self.myUtils.GetFileDLM(OutExcel)
            self.logger.debug("{0} - before save file rowCount : {1}".format(calling_func, self.uberTable.RowCount))
            self.uberTable.SaveToFile(OutExcel, fileDLM, self.OUTPUT_DATE_FORMAT, append,ll_NoHdrs)
            self.logger.debug("{0} - after save file rowCount : {1}".format(calling_func, self.uberTable.RowCount))
            rowCount = self.uberTable.RowCount
            self.myUtils.DoWriteDonePromptText(rowCount, incrementalRunCtr)
            return rowCount
        except Exception as err:
            errMsg = "Error : {0}".format(err.args[0])
            self.logger.exception("{0} - {1}".format(calling_func, err))
            raise Exception(errMsg)
            
    def saveMultiResultToFile(self, fetchChunkSize=10000, FirstConnect=True, OutExcel=None, WorkDir=".\\", outTTin=False, incrementalRunCtr=0, ll_NoHdrs=False) :
        """
        Save all the chunk data into final output
        """
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        startTime = time.perf_counter()
        try : 
            self.logger.debug("{0} - ll_NoHdrs : {1}".format(calling_func, ll_NoHdrs))
            self.logger.debug("{0} - FirstConnect : {1}".format(calling_func, FirstConnect))
            rowCount = 0
            total_rowCount = 0
            append = True
            if FirstConnect == True :
                append = False
            else :
                ll_NoHdrs = True

            self.logger.debug("{0} - ll_NoHdrs : {1}".format(calling_func, ll_NoHdrs))
            incr_out_files_list = []
            fileDLM = self.myUtils.GetFileDLM(OutExcel)

            idx = 1
            
            with SPFRichProgressBar(displayMofN=False) as progress: #, total=len(self.uberTables)):
                task = progress.add_task(f"Merging final output.....", total=len(self.uberTables))
                
                for uberTbl in self.uberTables:
                    if idx > 1:
                        append = True
                        ll_NoHdrs = True

                    uberTbl.SaveToFile(OutExcel, fileDLM, self.OUTPUT_DATE_FORMAT, append,ll_NoHdrs)

                    rowCount = uberTbl.RowCount
                    total_rowCount = total_rowCount + rowCount
                    self.myUtils.DoWriteDonePromptText(rowCount, idx)
                    idx = idx + 1
                    progress.update(task, advance=1)
                self.myUtils.Console("")
            self.myUtils.DoWriteDonePromptText(total_rowCount)
            return total_rowCount
        except Exception as err :
            errMsg = "Error : {0}".format(err.args[0])
            self.logger.exception("{0} - {1}".format(calling_func, err))
            raise Exception(errMsg)
        finally:
            try:
                timeTaken = time.perf_counter() - startTime
            except Exception as err:
                self.logger.warn("Unable to determine timeTaken value")
            
    def close(self, MyOLEDB, OutExcel, WkFile) :
        """
        ' close the connection object and any cleanup
        """
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        try:       
            self.uberTable = None
            self.UCHelper = None
            del self.uberTable
            del self.UCHelper
                 
            self.DataSource = None           
            del self.DataSource
            gc.collect()

            self.logger.info("{0} - Connection closed : clean up completed".format(calling_func))
        except Exception as err:
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise

    def Substitute_Facility(self, Sitei, SQLStr, MyMode = 'Y'):
        return self.substitute_facility(Sitei, SQLStr, MyMode)
#END : class dbDriverUBER #CLR

class dbDriverPYScript(dbDriverBase):
    """
    Python Script Driver
    """
    #region properties
    __execute_mode_is_inproc = True
    @property
    def execute_mode_is_inproc(self):
        return self.__execute_mode_is_inproc

    @execute_mode_is_inproc.setter
    def execute_mode_is_inproc(self, value: bool):
        self.__execute_mode_is_inproc = value
    #endregion properties
    def __init__(self):
        super(self.__class__, self).__init__()
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        return

    def openConnection(self, uni, pwi, InDBNode, ll_ConnRetry = True):
        """
        """
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        try:
            self.InDBNode = InDBNode
            self.ll_ConnRetry = ll_ConnRetry
            pass #nothing happens...just continue
        except Exception as err:
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise

    def execute_inproc(self, SQLQuery, CommandHdr = None, MyFetchSize = 10000, FirstConnect = True, ll_NoHdrs = False, OutExcel = None, OutFile = None, 
                WorkDir = '.\\', OutTT = False, FinalRow = 0, incrementalRunCtr = 0, doWriteDonePromptText = True, MyHeaders = None, py_script_file=None):
        """
        execute the pyscript (SQLQuery) in 'In-proc' mode i.e., execute with an 'import'
        """
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        self.logger.debug("{0} - py_script_file :: {1}".format(calling_func, py_script_file))
        
        try:
            #region in-proc2
            # my_py_script_to_run = imp.load_source(Path(py_script_file).stem, py_script_file)
            my_py_script_to_run = self.myUtils.load_py_module_source(Path(py_script_file).stem, py_script_file) #Py3.13 fix
            my_py_script_to_run.execute(self.gSPFExe, self.gSPFInstance)
            #endregion in-proc2
        except Exception as err:
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise
    #END: def execute_inproc

    def execute_outproc(self, SQLQuery, CommandHdr = None, MyFetchSize = 10000, FirstConnect = True, ll_NoHdrs = False, OutExcel = None, OutFile = None, 
                WorkDir = '.\\', OutTT = False, FinalRow = 0, incrementalRunCtr = 0, doWriteDonePromptText = True, MyHeaders = None, py_script_file=None):
        """
        execute the pyscript (SQLQuery) in 'Out-of-proc' mode i.e., execute using 'Utils.Run_Python()' method
        """
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        self.logger.debug("{0} - py_script_file :: {1}".format(calling_func, py_script_file))

        MyArgs = None 
        MyOS = "W" 
        ll_AppSvr = None 
        if self.gIsSvc is True:
            #executing in SQLPFaaS-HPC environment 
            l_WhichPy = "C3" # use the .ini entry
        else:
            #excuting in SH or Interactive or shared-VM
            l_WhichPy = "M" # will use the SPF Captive Python path
        
        try:
            #region out-of-proc invoke
            self.myUtils.Run_Python(py_script_file, MyArgs, MyOS, self.gMyLocal, self.gSPFInstance, ll_AppSvr, l_WhichPy)
            #endregion out-of-proc invoke
        except Exception as err:
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise
    #END :  def execute_outproc

    def execute(self, SQLQuery, CommandHdr = None, MyFetchSize = 10000, FirstConnect = True, ll_NoHdrs = False, OutExcel = None, OutFile = None, 
                WorkDir = '.\\', OutTT = False, FinalRow = 0, incrementalRunCtr = 0, doWriteDonePromptText = True, MyHeaders = None):
        """
        """
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        self.logger.debug("{0} - queryOptions :: {1}".format(calling_func, self.queryOptions))
        self.logger.debug("{0} - SQLQuery: {1}".format(calling_func, SQLQuery))
        self.logger.debug("{0} - CommandHdr: {1}".format(calling_func, CommandHdr))
        self.logger.debug("{0} - MyFetchSize: {1}".format(calling_func, MyFetchSize))
        self.logger.debug("{0} - FirstConnect: {1}".format(calling_func, FirstConnect))
        self.logger.debug("{0} - ll_NoHdrs: {1}".format(calling_func, ll_NoHdrs))
        self.logger.debug("{0} - OutExcel: {1}".format(calling_func, OutExcel))
        self.logger.debug("{0} - OutFile: {1}".format(calling_func, OutFile))
        self.logger.debug("{0} - WorkDir: {1}".format(calling_func, WorkDir))
        self.logger.debug("{0} - OutTT: {1}".format(calling_func, OutTT))
        self.logger.debug("{0} - FinalRow: {1}".format(calling_func, FinalRow))
        self.logger.debug("{0} - incrementalRunCtr: {1}".format(calling_func, incrementalRunCtr))
        self.logger.debug("{0} - MyHeaders: {1}".format(calling_func, MyHeaders))
        self.logger.debug("{0} - execute_mode_is_inproc: {1}".format(calling_func, self.execute_mode_is_inproc))

        
        my_pyscript = str(Path(f"spfpdr_{self.RNStrNew}_{self.gSPFInstance}_script.spfps").absolute())

        try:
            self.logger.debug("{0} - my_pyscript: {1}".format(calling_func, my_pyscript))
            self.myUtils.DoCreateFileA(my_pyscript, SQLQuery, self.__class__.__name__)
            self.logger.debug("{0} - exists my_pyscript: {1}".format(calling_func, Path(my_pyscript).exists()) )

            if self.execute_mode_is_inproc is True:
                method_to_invoke = self.execute_inproc
            else:
                method_to_invoke = self.execute_outproc
            
            method_to_invoke(SQLQuery, CommandHdr = CommandHdr, MyFetchSize = MyFetchSize, FirstConnect = FirstConnect, ll_NoHdrs = ll_NoHdrs, OutExcel = OutExcel, OutFile = OutFile, 
                WorkDir = WorkDir, OutTT = OutTT, FinalRow = FinalRow, incrementalRunCtr = incrementalRunCtr, doWriteDonePromptText = doWriteDonePromptText, MyHeaders = MyHeaders, py_script_file=my_pyscript)
            
            rowCnt = self.myUtils.getRowCountFromFile(OutExcel)
            return rowCnt
        except Exception as err:
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise
        finally:
            if self.logger.level != 10: #DEBUG Mode
                self.myUtils.DelAFile(my_pyscript)

    #END : def execute
#END : dbDriverPYScript

class dbDriverDuckDB(dbDriverBase):
    """
    DuckDb driver
    """
    def __init__(self):
        super(self.__class__, self).__init__()
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        self.ddb_table_map = {}
        return

    def __import_csv(self, source_file_to_load, table_name):
        """
        create a duckdb function call for loading of CSV/TAB files
        """
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        _dlm = self.myUtils.GetFileDLM(str(source_file_to_load))
        ddb_table = f"read_csv_auto('{source_file_to_load}', delim='{_dlm}', quote='\"', header=True, NULLSTR='', all_varchar=True, timestampformat='{self.G_DT_FORMAT_YYYY_MM_DD_HH24_MM_SS}')"
        return ddb_table
    #END: def __import_csv

    def __import_parquet(self, source_file_to_load, table_name):
        """
        create a duckdb function call for loading of 'parquet' files
        """
        ddb_prq_tbl = f"read_parquet('{source_file_to_load}')"
        return ddb_prq_tbl
    #END : def __import_parquet

    def openConnection(self, uni, pwi, InDBNode, ll_ConnRetry = True):
        """
        setup connection to DuckDB instance
        """
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        split_token="@@@@@"
        
        try:
            self.InDBNode = InDBNode
            self.ll_ConnRetry = ll_ConnRetry
            self.connectionObject = duckdb.connect(database="")

            self.logger.debug("{0} - InDBNode : '{1}'".format(calling_func, InDBNode))
            try:
                #####################################################################################
                # parse --> /NODE=DUCKDB:<source file>:<table name>
                #          /NODE=DUCKDB:<source file>:<table name>@@@@@DUCKDB:<source file>:<table name>
                # E.g.,
                # /NODE=DUCKDB:.\test_prq_in.parquet:test_prq_in
                # /NODE=DUCKDB:.\test_prq_in.parquet:test_prq_in@@@@@DUCKDB:.\test_prq_in.csv:test_csv_in
                ######################################################################################

                ptrn = re.compile("(.*?):(.*):(.*)$", re.IGNORECASE)
                InDBNode_split_list = InDBNode.split(split_token)
                self.logger.debug("{0} - InDBNode_split_list : '{1}'".format(calling_func, InDBNode_split_list))
                for InDBNode_Item in InDBNode_split_list:
                    InDBNode_Item_splits = list(re.match(ptrn, InDBNode_Item.strip()).groups())
                    self.logger.debug("{0} - InDBNode_Item_splits : '{1}'".format(calling_func, InDBNode_Item_splits))
                    _source_file_to_load = Path(InDBNode_Item_splits[1]) #get the source file(s) -- note: support widlcards ? * (only name part...not file extension part)
                    # check if source file path has wildcards
                    if re.search(r"\*|\?", str(_source_file_to_load)) is None:
                        # no wildcard specified in path...ensure file exists
                        if _source_file_to_load.is_file() is False:
                            raise Exception(f"Source file not found : {_source_file_to_load}")
                    table_name = InDBNode_Item_splits[2] #get 'table name' to used in duckdb for specified source file(s)
                    _source_file_extension = _source_file_to_load.suffix.upper() #get source file extension -- wild card not supported in file extension part
                    self.logger.debug(f"{calling_func} - source_file_to_load : '{_source_file_to_load}'; table_name : {table_name}; source_file_extension : {_source_file_extension}")
                    # check if source file path has wildcards
                    if re.search(r"\*|\?", str(_source_file_to_load)) is None:
                        # no wildcard specified in path...ensure file exists
                        if _source_file_to_load.is_file() is False:
                            raise Exception(f"Source file not found : {_source_file_to_load}")

                    #based on file type being loaded...route to correct method to create a duckdb inline function string
                    if _source_file_extension == ".PARQUET":
                        
                        self.ddb_table_map[table_name] = self.__import_parquet(_source_file_to_load, table_name)
                    elif _source_file_extension in [".CSV", '.TAB']:
                        # this will create 'read'
                        self.ddb_table_map[table_name] = self.__import_csv(_source_file_to_load, table_name)
                    else:
                        raise Exception(f"Input file of {'_source_file_extension'} extension not supported")

                self.logger.debug("{0} - con obj created : {1}; DuckDB.Version : {2}".format(calling_func, self.connectionObject, duckdb.__version__))
                
            except Exception as err:
                self.logger.exception(f"Error while parsing DuckDB NODE value : '{err}'")
                raise
            self.logger.debug("{0} - con obj created : {1}; DuckDB.Version : {2}".format(calling_func, self.connectionObject, duckdb.__version__))

        except Exception as err:
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise
    #END: def openConnection
    
    def substitute_ddb_table(self, sqlquery):
        """
        substitute sql table with relevant ddb file read functions from ddb_table_map dict
        Note: ddb_table_map will be populated in 'openConnection()'
        """
        try:
            self.logger.debug(f"ddb_table_map : {self.ddb_table_map}")
            for ddb_tbl_key, ddb_tbl_func in self.ddb_table_map.items():
                self.logger.debug(f"ddb_tbl_key {ddb_tbl_key} - ddb_tbl_func {ddb_tbl_func}")
                sqlquery = re.sub(rf'\<DDBTable\>{ddb_tbl_key}\<\/DDBTable\>', ddb_tbl_func, sqlquery, count=0, flags=re.IGNORECASE)
            self.logger.debug(f"sqlquery : {sqlquery}")
        except Exceptionn as err:
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise
        return sqlquery
    
    def execute(self, SQLQuery, CommandHdr = None, MyFetchSize = 10000, FirstConnect = True, ll_NoHdrs = False, OutExcel = None, OutFile = None, 
                WorkDir = '.\\', OutTT = False, FinalRow = 0, incrementalRunCtr = 0, doWriteDonePromptText = True, MyHeaders = None):
        """
        execut SQL query
        """
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        self.logger.debug("{0} - queryOptions :: {1}".format(calling_func, self.queryOptions))
        self.logger.debug("{0} - SQLQuery: {1}".format(calling_func, SQLQuery))
        self.logger.debug("{0} - CommandHdr: {1}".format(calling_func, CommandHdr))
        self.logger.debug("{0} - MyFetchSize: {1}".format(calling_func, MyFetchSize))
        self.logger.debug("{0} - FirstConnect: {1}".format(calling_func, FirstConnect))
        self.logger.debug("{0} - ll_NoHdrs: {1}".format(calling_func, ll_NoHdrs))
        self.logger.debug("{0} - OutExcel: {1}".format(calling_func, OutExcel))
        self.logger.debug("{0} - OutFile: {1}".format(calling_func, OutFile))
        self.logger.debug("{0} - WorkDir: {1}".format(calling_func, WorkDir))
        self.logger.debug("{0} - OutTT: {1}".format(calling_func, OutTT))
        self.logger.debug("{0} - FinalRow: {1}".format(calling_func, FinalRow))
        self.logger.debug("{0} - incrementalRunCtr: {1}".format(calling_func, incrementalRunCtr))
        self.logger.debug("{0} - MyHeaders: {1}".format(calling_func, MyHeaders))      
        
        cur_rowcount = 0 #init to 0
        SQLQuery = self.substitute_ddb_table(SQLQuery) # substitute sql table name with ddb function calls
        self.cursorObject = self.connectionObject.execute(SQLQuery)
        cur_rowcount = cur_rowcount + self.writeCursorToFile(MyFetchSize,FirstConnect,OutExcel, WorkDir, OutTT, incrementalRunCtr, ll_NoHdrs, MyHeaders)
        
        return cur_rowcount
    #END : def execute()

    def writeCursorToFile(self, fetchChunkSize=10000, FirstConnect = True, OutExcel=None, 
                            WorkDir=".\\", outTTin=False, incrementalRunCtr=0, ll_NoHdrs=False, MyHeaders=None) :
        """
        override from base.
        DuckDB 0.4.0 doesn't support Pythong-DB-API : 'fetchmany(chunksize)'. But seems to be supported in 0.7x...once we move to the latest version. This method can be removed
        """
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        self.logger.debug("{0} - queryOptions :: {1}".format(calling_func, self.queryOptions))
        self.logger.info("{0} - fetchChunkSize : {1}".format(calling_func, fetchChunkSize))
        self.logger.info("{0} - FirstConnect : {1}".format(calling_func, FirstConnect))
        self.logger.info("{0} - OutExcel : {1}".format(calling_func, OutExcel))
        self.logger.info("{0} - WorkDir : {1}".format(calling_func, WorkDir))
        self.logger.info("{0} - outTTin : {1}".format(calling_func, outTTin))
        self.logger.info("{0} - incrementalRunCtr : {1}".format(calling_func, incrementalRunCtr))
        self.logger.info("{0} - ll_NoHdrs : {1}".format(calling_func, ll_NoHdrs))
        self.logger.info("{0} - MyHeaders : {1}".format(calling_func, MyHeaders))
        file_OutExcel = None       
        rowCount = 0
        fileDLM = None
        cleanupTempOutExcel = False
        try:
            myCursorObject = self.cursorObject #note this is initialized during execute method
            if myCursorObject is None : 
                errMsg = "cursor object is not set"
                raise Exception(errMsg)
            if self.myUtils.IsEmptyOrNone(OutExcel) is True:
                if outTTin is False:  #just display the rowcount to terminal
                    # rowChunks = myCursorObject.fetchmany(fetchChunkSize) # this is not supported in 0.4.0 version of DuckDB..will need 0.7.0+
                    # while rowChunks:                       
                    #     rowCount = rowCount+ len(rowChunks)
                    #     self.logger.info("{0} - fetched rows : {1}".format(calling_func, rowCount))
                    #     rowChunks = myCursorObject.fetchmany(fetchChunkSize)
                    rowChunks  = myCursorObject.fetchall()
                    if rowChunks:
                        rowCount = rowCount+ len(rowChunks)
                    self.myUtils.DoWriteDonePromptText(rowCount, incrementalRunCtr)
                    return rowCount #no 
                else: #no output file...but need to display to terminal
                    cleanupTempOutExcel = True #set flag to cleanup temp OutExcel in the end(finally block)
                    OutExcel = "tmp_{0}_{0}.tab".format(self.gSPFInstance, self.RNStrNew)

            self.logger.info("{0} - start writing to file : {1}".format(calling_func, OutExcel))
            startTime = time.perf_counter()
            try :
                fileDLM = self.myUtils.GetFileDLM(OutExcel, mode="O")
            except Exception as err:
                fileNamePart, fileExtPart = os.path.splitext(OutExcel)
                self.logger.info("FileNamePart = {0}, FileExtPart = {1}".format(fileNamePart, fileExtPart))
                outputHandlerMethodObj = getattr(self, self.outputFileWriterMap[fileExtPart.lower()]) 
                self.logger.debug("{0} - outputHandlerMethodObj : {1}".format(calling_func, outputHandlerMethodObj))
                raise
            if fileDLM == "": #need to print to .txt file
                return self.myUtils.writeCursorToTxtFile(myCursorObject, fetchChunkSize, FirstConnect, OutExcel,WorkDir,outTTin,incrementalRunCtr, ll_NoHdrs)
                #done writing to a .TXT file
            fileMode = 'a' if FirstConnect is False else 'w'
            self.logger.debug("{0} - fileMode = {1}".format(calling_func, fileMode))
            
            with open(OutExcel, fileMode, encoding=self.gOSDefaultEncoding, errors='replace') as file_OutExcel:
                file_OutExcel_writer = csv.writer(file_OutExcel, delimiter=fileDLM, lineterminator=self.gLineTerminator)
                
                if FirstConnect is True and ll_NoHdrs is False:
                    self.logger.debug("{0} - cursor.description = {1}".format(calling_func, myCursorObject.description))
                    if myCursorObject.description is not None:
                        columns = [i[0].upper() for i in myCursorObject.description]
                    else:
                        columns = MyHeaders.split(",")
                    
                    file_OutExcel_writer.writerow(columns)
                    self.logger.info("{0} - write header completed : {1}".format(calling_func, columns))

                # self.logger.debug("about to start rows")
                # rows = myCursorObject.fetchmany(fetchChunkSize) # this is not supported in 0.4.0 version of DuckDB..will need 0.7.0+
                # while rows:                                         
                #     rowCount = rowCount+ len(rows)          
                #     file_OutExcel_writer.writerows(rows)
                #     self.logger.info("{0} - written rows : {1}".format(calling_func, rowCount))
                    # rows = myCursorObject.fetchmany(fetchChunkSize)
            #END : with open
            rowChunks = myCursorObject.fetch_record_batch(fetchChunkSize)
            writemode = "a"
            myheader=False
            for chunk in rowChunks:
                df = chunk.to_pandas()
                rowCount = rowCount+ len(df)    
                df.to_csv(OutExcel, mode=writemode, index=False, header=myheader, chunksize=fetchChunkSize, sep=fileDLM)
                # myheader=False
                # writemode = "a"
            timeTaken = time.perf_counter() - startTime
            self.logger.info("{0} - Done writing {1} records to file : '{2}'; Response Time: {3}".format(calling_func, rowCount, OutExcel, timeTaken))
            self.myUtils.DoWriteDonePromptText(rowCount, incrementalRunCtr)
            return rowCount
        except IOError as IOerr:
            errMsg = "I/O Error({0}): {1} \n File : {2}".format(IOerr.errno, IOerr.strerror, IOerr.filename)
            self.logger.exception("{0} - {1}".format(calling_func, errMsg))
            raise Exception(errMsg)
        except Exception as err:
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise
        finally:
            self.logger.info("{0} - In finally block".format(calling_func))
            if not file_OutExcel is None: 
                if not file_OutExcel.closed: 
                    self.logger.info("{0} - File was not closed...will close now".format(calling_func))
                    try : 
                        file_OutExcel.close()
                    except Exception as err:
                        self.logger.warn("{0} - not able to close File in finally block".format(calling_func))
                else:
                    self.logger.info("{0} - File is closed...".format(calling_func))
                if cleanupTempOutExcel is True:
                    self.myUtils.DelAFile(OutExcel) #this is a temp file when OutExcel == "" and OutTTIn == True
    #END : def writeCursorToFile

#END : class dbDriverDuckDB

class dbDriverODBCSnowflake(dbDriverODBCBase):
    """
    ' This is the ODBC wrapper -- SNOWFLAKE
    """
    #locals for this driver class
    
    __OpenConTimeOut = 15 # in seconds
    __OpenConRetryCount = 3
    __OpenConRetrySleepInterval = 15 # in seconds
    ll_ConnRetry = False
    connectionObject = None
    

    def __init__(self) :
        super(self.__class__, self).__init__()
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        try:
            self.odbcDriverName = 'SnowflakeDSIIDriver'
            self.OpenConnErrCodesForRetry = [] #list all the connection related error codes for which retry should be triggered
            self.logger.info("{0} : {1} Initialized".format(calling_func, self.__class__.__name__))
        except Exception as err:
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise

    def genConnectionString(self, uni, pwi, InDBNode) :
        """
        ' Override base method - specific driver implementation
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        self.logger.debug("{0} - create conn string for : {1}".format(calling_func, self.strip_connection(InDBNode)))
        #self.logger.debug("{0} - InDBNode: {1}".format(calling_func, InDBNode))
        try:
            InDBNodeSplits = InDBNode.split("@")
            DataSource = InDBNodeSplits[0]
            #for Denodo this is a System DSN...
            DataSource, DSNType = self.checkDSNExists(DataSource)
            
            self.logger.info("{0} - DataSource: {1}; uni = {2}".format(calling_func, DataSource, uni))
            if self.myUtils.IsEmptyOrNone(uni) is True:
                # IWA
                self.connectString = f"{DSNType}={DataSource};UID={self.myUtils.gUserPrincipal}"
            else:
                # DB UN
                self.connectString = f"{DSNType}={DataSource};UID={uni}"

            #TODO : comment out below line to hide sensitive info
            self.logger.debug("{0} - connectString : {1}".format(calling_func, self.myUtils.maskSensitiveInfo(self.connectString)))
            return self.connectString
        except Exception as err:
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise
    
    def execute(self, SQLQuery, CommandHdr=None, MyFetchSize=10000, FirstConnect= True, ll_NoHdrs=False,
                OutExcel=None, OutFile=None, WorkDir=".\\", OutTT=False, FinalRow=0, incrementalRunCtr=0, doWriteDonePromptText=True, MyHeaders=None):
        """
        override base method to execute session level settings for Snowflake
        """
        self.cursorObject = self.connectionObject.cursor()
        # self.cursorObject.execute("SHOW PARAMETERS LIKE 'QUOTED_IDENTIFIERS%'")

        # _SQLQuery = "ALTER SESSION SET MULTI_STATEMENT_COUNT = 0"
        _SQLQuery = "ALTER SESSION SET QUOTED_IDENTIFIERS_IGNORE_CASE = FALSE"
        self.cursorObject.execute(_SQLQuery)
        
        self.cursorObject.execute(SQLQuery)
        
        cur_rowcount = self.writeCursorToFile(MyFetchSize,FirstConnect,OutExcel, WorkDir, OutTT, incrementalRunCtr, ll_NoHdrs,MyHeaders, Cols_To_UCase = False)
        return cur_rowcount
#END : class dbDriverODBCSnowflake

#endregion -- DBDrivers


